/**
 * AccessibleModal Component
 *
 * A fully accessible modal dialog component with:
 * - Focus trap (keeps focus within modal)
 * - ESC key handler
 * - ARIA attributes (role="dialog", aria-modal="true")
 * - Automatic focus management
 * - Screen reader announcements
 * - Backdrop click to close
 *
 * WCAG 2.1 AA Compliant
 *
 * Usage:
 * ```jsx
 * <AccessibleModal
 *   isOpen={isOpen}
 *   onClose={handleClose}
 *   title="Modal Title"
 *   description="Optional description"
 * >
 *   <p>Modal content</p>
 * </AccessibleModal>
 * ```
 */

import React, { useEffect, useRef } from 'react';
import { X } from 'lucide-react';

const AccessibleModal = ({
  isOpen,
  onClose,
  title,
  description,
  children,
  size = 'medium', // 'small', 'medium', 'large', 'full'
  showCloseButton = true,
  closeOnBackdropClick = true,
  closeOnEscape = true,
  className = '',
}) => {
  const modalRef = useRef(null);
  const closeButtonRef = useRef(null);
  const previousFocusRef = useRef(null);

  // Store the element that had focus before modal opened
  useEffect(() => {
    if (isOpen) {
      previousFocusRef.current = document.activeElement;
    }
  }, [isOpen]);

  // Focus trap and keyboard navigation
  useEffect(() => {
    if (!isOpen) return;

    const modal = modalRef.current;
    if (!modal) return;

    // Get all focusable elements
    const focusableElements = modal.querySelectorAll(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );
    const firstElement = focusableElements[0];
    const lastElement = focusableElements[focusableElements.length - 1];

    // Focus first element (close button or first focusable)
    if (closeButtonRef.current) {
      closeButtonRef.current.focus();
    } else if (firstElement) {
      firstElement.focus();
    }

    // Handle tab key for focus trap
    const handleTab = (e) => {
      if (e.key !== 'Tab') return;

      if (e.shiftKey) {
        // Shift + Tab
        if (document.activeElement === firstElement) {
          e.preventDefault();
          lastElement.focus();
        }
      } else {
        // Tab
        if (document.activeElement === lastElement) {
          e.preventDefault();
          firstElement.focus();
        }
      }
    };

    // Handle escape key
    const handleEscape = (e) => {
      if (e.key === 'Escape' && closeOnEscape) {
        onClose();
      }
    };

    modal.addEventListener('keydown', handleTab);
    modal.addEventListener('keydown', handleEscape);

    // Cleanup
    return () => {
      modal.removeEventListener('keydown', handleTab);
      modal.removeEventListener('keydown', handleEscape);

      // Restore focus to previous element
      if (previousFocusRef.current) {
        previousFocusRef.current.focus();
      }
    };
  }, [isOpen, onClose, closeOnEscape]);

  // Prevent body scroll when modal is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }

    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  // Handle backdrop click
  const handleBackdropClick = (e) => {
    if (closeOnBackdropClick && e.target === e.currentTarget) {
      onClose();
    }
  };

  if (!isOpen) return null;

  // Size classes
  const sizeClasses = {
    small: 'max-w-md',
    medium: 'max-w-2xl',
    large: 'max-w-4xl',
    full: 'max-w-full mx-4',
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-50"
      onClick={handleBackdropClick}
    >
      <div
        ref={modalRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? 'modal-title' : undefined}
        aria-describedby={description ? 'modal-description' : undefined}
        onClick={(e) => e.stopPropagation()}
        className={`bg-white rounded-lg shadow-xl w-full ${sizeClasses[size]} max-h-[90vh] overflow-y-auto ${className}`}
      >
        {/* Header */}
        <div className="flex items-start justify-between p-6 border-b border-gray-200">
          <div className="flex-1">
            {title && (
              <h2
                id="modal-title"
                className="text-xl font-bold text-gray-900"
              >
                {title}
              </h2>
            )}
            {description && (
              <p
                id="modal-description"
                className="mt-1 text-sm text-gray-600"
              >
                {description}
              </p>
            )}
          </div>
          {showCloseButton && (
            <button
              ref={closeButtonRef}
              onClick={onClose}
              className="ml-4 p-1 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded transition-colors"
              aria-label="Close dialog"
            >
              <X className="w-6 h-6" aria-hidden="true" />
            </button>
          )}
        </div>

        {/* Content */}
        <div className="p-6">{children}</div>
      </div>
    </div>
  );
};

export default AccessibleModal;

/**
 * AccessibleModal Component Tests
 *
 * Tests the accessible modal component for:
 * - WCAG 2.1 AA compliance
 * - Focus trap functionality
 * - Keyboard navigation (ESC to close)
 * - ARIA attributes
 * - Focus restoration
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import AccessibleModal from './AccessibleModal';

describe('AccessibleModal Component', () => {
  const mockOnClose = vi.fn();

  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Rendering', () => {
    it('should not render when isOpen is false', () => {
      render(
        <AccessibleModal isOpen={false} onClose={mockOnClose} title="Test Modal">
          <p>Content</p>
        </AccessibleModal>
      );

      expect(screen.queryByText('Test Modal')).not.toBeInTheDocument();
    });

    it('should render when isOpen is true', () => {
      render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal">
          <p>Content</p>
        </AccessibleModal>
      );

      expect(screen.getByText('Test Modal')).toBeInTheDocument();
      expect(screen.getByText('Content')).toBeInTheDocument();
    });

    it('should render with description', () => {
      render(
        <AccessibleModal
          isOpen={true}
          onClose={mockOnClose}
          title="Test Modal"
          description="This is a description"
        >
          <p>Content</p>
        </AccessibleModal>
      );

      expect(screen.getByText('This is a description')).toBeInTheDocument();
    });

    it('should render close button by default', () => {
      render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal">
          <p>Content</p>
        </AccessibleModal>
      );

      expect(screen.getByRole('button', { name: /close dialog/i })).toBeInTheDocument();
    });

    it('should not render close button when showCloseButton is false', () => {
      render(
        <AccessibleModal
          isOpen={true}
          onClose={mockOnClose}
          title="Test Modal"
          showCloseButton={false}
        >
          <p>Content</p>
        </AccessibleModal>
      );

      expect(screen.queryByRole('button', { name: /close dialog/i })).not.toBeInTheDocument();
    });
  });

  describe('Accessibility - WCAG 2.1 AA Compliance', () => {
    it('should have role="dialog"', () => {
      render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal">
          <p>Content</p>
        </AccessibleModal>
      );

      expect(screen.getByRole('dialog')).toBeInTheDocument();
    });

    it('should have aria-modal="true"', () => {
      render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal">
          <p>Content</p>
        </AccessibleModal>
      );

      const dialog = screen.getByRole('dialog');
      expect(dialog).toHaveAttribute('aria-modal', 'true');
    });

    it('should have aria-labelledby pointing to title', () => {
      render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal">
          <p>Content</p>
        </AccessibleModal>
      );

      const dialog = screen.getByRole('dialog');
      const titleId = dialog.getAttribute('aria-labelledby');
      expect(titleId).toBe('modal-title');

      const title = document.getElementById(titleId);
      expect(title).toHaveTextContent('Test Modal');
    });

    it('should have aria-describedby when description is provided', () => {
      render(
        <AccessibleModal
          isOpen={true}
          onClose={mockOnClose}
          title="Test Modal"
          description="Test description"
        >
          <p>Content</p>
        </AccessibleModal>
      );

      const dialog = screen.getByRole('dialog');
      const descId = dialog.getAttribute('aria-describedby');
      expect(descId).toBe('modal-description');

      const description = document.getElementById(descId);
      expect(description).toHaveTextContent('Test description');
    });
  });

  describe('Keyboard Navigation', () => {
    it('should close modal on ESC key', async () => {
      const user = userEvent.setup();
      render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal">
          <p>Content</p>
        </AccessibleModal>
      );

      await user.keyboard('{Escape}');

      expect(mockOnClose).toHaveBeenCalled();
    });

    it('should not close on ESC when closeOnEscape is false', async () => {
      const user = userEvent.setup();
      render(
        <AccessibleModal
          isOpen={true}
          onClose={mockOnClose}
          title="Test Modal"
          closeOnEscape={false}
        >
          <p>Content</p>
        </AccessibleModal>
      );

      await user.keyboard('{Escape}');

      expect(mockOnClose).not.toHaveBeenCalled();
    });

    it('should trap focus within modal', async () => {
      const user = userEvent.setup();
      render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal">
          <button>Button 1</button>
          <button>Button 2</button>
          <button>Button 3</button>
        </AccessibleModal>
      );

      // Initial focus should be on close button
      const closeButton = screen.getByRole('button', { name: /close dialog/i });
      expect(closeButton).toHaveFocus();
    });
  });

  describe('Interaction', () => {
    it('should close when close button is clicked', async () => {
      const user = userEvent.setup();
      render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal">
          <p>Content</p>
        </AccessibleModal>
      );

      const closeButton = screen.getByRole('button', { name: /close dialog/i });
      await user.click(closeButton);

      expect(mockOnClose).toHaveBeenCalled();
    });

    it('should close when backdrop is clicked', async () => {
      const user = userEvent.setup();
      const { container } = render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal">
          <p>Content</p>
        </AccessibleModal>
      );

      const backdrop = container.querySelector('[role="dialog"]').parentElement;
      await user.click(backdrop);

      expect(mockOnClose).toHaveBeenCalled();
    });

    it('should not close on backdrop click when closeOnBackdropClick is false', async () => {
      const user = userEvent.setup();
      const { container } = render(
        <AccessibleModal
          isOpen={true}
          onClose={mockOnClose}
          title="Test Modal"
          closeOnBackdropClick={false}
        >
          <p>Content</p>
        </AccessibleModal>
      );

      const backdrop = container.querySelector('[role="dialog"]').parentElement;
      await user.click(backdrop);

      expect(mockOnClose).not.toHaveBeenCalled();
    });
  });

  describe('Size Variants', () => {
    it('should apply small size class', () => {
      const { container } = render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal" size="small">
          <p>Content</p>
        </AccessibleModal>
      );

      const modal = container.querySelector('.max-w-md');
      expect(modal).toBeInTheDocument();
    });

    it('should apply medium size class by default', () => {
      const { container } = render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal">
          <p>Content</p>
        </AccessibleModal>
      );

      const modal = container.querySelector('.max-w-2xl');
      expect(modal).toBeInTheDocument();
    });

    it('should apply large size class', () => {
      const { container } = render(
        <AccessibleModal isOpen={true} onClose={mockOnClose} title="Test Modal" size="large">
          <p>Content</p>
        </AccessibleModal>
      );

      const modal = container.querySelector('.max-w-4xl');
      expect(modal).toBeInTheDocument();
    });
  });
});

