import React, { useState, useEffect, useMemo } from "react";
import {
  Activity,
  CheckCircle,
  XCircle,
  Clock,
  AlertTriangle,
  TrendingUp,
  Target,
  DollarSign,
  Calendar,
  ChevronRight,
  Filter,
  Download,
  Search,
  ArrowUpDown,
  CreditCard,
} from "lucide-react";
import { useOrganization } from "../contexts/OrganizationContext";

const AgentActivityMonitor = ({ mandates, stats }) => {
  const [filter, setFilter] = useState("all"); // 'all', 'cart', 'payment'
  const [statusFilter, setStatusFilter] = useState("all"); // 'all', 'pending', 'active', 'completed', 'failed', 'revoked'
  const [searchQuery, setSearchQuery] = useState("");
  const [sortBy, setSortBy] = useState("newest"); // 'newest', 'oldest', 'amount_high', 'amount_low', 'status'
  const [sortedMandates, setSortedMandates] = useState([]);

  // Exclude intent mandates — they have their own Reusable Authorizations tab
  const transactions = mandates.filter((m) => m.type === "cart" || m.type === "payment");

  // Group cart + payment mandates by cart_mandate_id
  const { groupedItems, standalonePayments } = useMemo(() => {
    const carts = transactions.filter((m) => m.type === "cart");
    const payments = transactions.filter((m) => m.type === "payment");

    const cartMap = new Map();
    carts.forEach((c) => cartMap.set(c.id, { cart: c, payment: null }));

    const standalone = [];
    payments.forEach((p) => {
      if (p.cart_mandate_id && cartMap.has(p.cart_mandate_id)) {
        cartMap.get(p.cart_mandate_id).payment = p;
      } else {
        standalone.push(p);
      }
    });

    return {
      groupedItems: Array.from(cartMap.values()),
      standalonePayments: standalone,
    };
  }, [mandates]);

  // Sort and filter mandates
  useEffect(() => {
    let displayItems = [];

    if (filter === "payment") {
      // Flat payment list — no grouping
      displayItems = transactions
        .filter((m) => m.type === "payment")
        .map((p) => ({ ...p, _payment: null }));
    } else {
      // Grouped view: cart as primary, payment nested
      groupedItems.forEach((g) => {
        displayItems.push({
          ...g.cart,
          _payment: g.payment,
        });
      });
      // "all" also includes standalone payments (no matching cart)
      if (filter === "all") {
        standalonePayments.forEach((p) => {
          displayItems.push({ ...p, _payment: null });
        });
      }
    }

    // Status filter
    if (statusFilter !== "all") {
      displayItems = displayItems.filter((m) => m.status === statusFilter);
    }

    // Search filter
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      displayItems = displayItems.filter(
        (m) =>
          m.id.toLowerCase().includes(query) ||
          (m.merchant && m.merchant.toLowerCase().includes(query)) ||
          (m.total && m.total.toString().includes(query)) ||
          (m.payment_method && m.payment_method.toLowerCase().includes(query)) ||
          (m._payment?.payment_method &&
            m._payment.payment_method.toLowerCase().includes(query)) ||
          (m._payment?.id && m._payment.id.toLowerCase().includes(query)),
      );
    }

    // Sort
    displayItems.sort((a, b) => {
      switch (sortBy) {
        case "oldest":
          return new Date(a.created_at) - new Date(b.created_at);
        case "amount_high":
          return (parseFloat(b.total) || 0) - (parseFloat(a.total) || 0);
        case "amount_low":
          return (parseFloat(a.total) || 0) - (parseFloat(b.total) || 0);
        case "status":
          return (a.status || "").localeCompare(b.status || "");
        case "newest":
        default:
          return new Date(b.created_at) - new Date(a.created_at);
      }
    });

    setSortedMandates(displayItems);
  }, [groupedItems, standalonePayments, filter, statusFilter, searchQuery, sortBy]);

  // Calculate statistics — count groups, not individual mandates
  const statsItems = useMemo(() => {
    if (filter === "payment") {
      return transactions.filter((m) => m.type === "payment");
    }
    const items = groupedItems.map((g) => g.cart);
    if (filter === "all") {
      return [...items, ...standalonePayments];
    }
    return items; // filter === "cart"
  }, [groupedItems, standalonePayments, filter, mandates]);

  const totalTransactions = statsItems.length;
  const completedCount = statsItems.filter((m) => m.status === "completed").length;
  const activeCount = statsItems.filter((m) => m.status === "active").length;
  const pendingCount = statsItems.filter((m) => m.status === "pending").length;
  const failedCount = statsItems.filter((m) => m.status === "failed").length;
  const revokedCount = statsItems.filter((m) => m.status === "revoked").length;

  return (
    <div className="space-y-6">
      {/* Header & Stats */}
      <div>
        <h2 className="text-2xl font-bold text-gray-900 mb-1">
          Agent Activity
        </h2>
        <p className="text-sm text-gray-500 mb-6">Purchase requests and payment history</p>

        {/* Quick Stats */}
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3 mb-6">
          <StatCard
            icon={<Activity className="w-5 h-5" />}
            label="Total"
            value={totalTransactions}
            color="blue"
          />
          <StatCard
            icon={<CheckCircle className="w-5 h-5" />}
            label="Completed"
            value={completedCount}
            color="green"
          />
          <StatCard
            icon={<Clock className="w-5 h-5" />}
            label="Active"
            value={activeCount}
            color="yellow"
          />
          <StatCard
            icon={<Clock className="w-5 h-5" />}
            label="Pending"
            value={pendingCount}
            color="purple"
          />
          <StatCard
            icon={<XCircle className="w-5 h-5" />}
            label="Failed"
            value={failedCount}
            color="red"
          />
          <StatCard
            icon={<XCircle className="w-5 h-5" />}
            label="Revoked"
            value={revokedCount}
            color="orange"
          />
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4">
        <div className="flex flex-col md:flex-row md:items-center md:space-x-4 space-y-4 md:space-y-0">
          {/* Search */}
          <div className="flex-1">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                placeholder="Search by ID, merchant, amount..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-600 focus:border-transparent"
              />
            </div>
          </div>

          {/* Type Filter */}
          <div className="flex space-x-2">
            <span className="text-sm font-medium text-gray-700 self-center">
              Type:
            </span>
            {[
              { value: "all", label: "All" },
              { value: "cart", label: "Purchase Requests" },
              { value: "payment", label: "Payments" },
            ].map(({ value, label }) => (
              <button
                key={value}
                onClick={() => setFilter(value)}
                className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
                  filter === value
                    ? "bg-purple-100 text-purple-700"
                    : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                }`}
              >
                {label}
              </button>
            ))}
          </div>

          {/* Status Filter */}
          <div className="flex space-x-2">
            <span className="text-sm font-medium text-gray-700 self-center">
              Status:
            </span>
            {["all", "active", "pending", "completed", "failed", "revoked"].map((status) => (
              <button
                key={status}
                onClick={() => setStatusFilter(status)}
                className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
                  statusFilter === status
                    ? "bg-purple-100 text-purple-700"
                    : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                }`}
              >
                {status.charAt(0).toUpperCase() + status.slice(1)}
              </button>
            ))}
          </div>

          {/* Sort */}
          <div className="flex items-center space-x-2">
            <ArrowUpDown className="w-4 h-4 text-gray-500" />
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
              className="text-sm border border-gray-300 rounded-lg px-3 py-1.5 focus:ring-2 focus:ring-purple-600 focus:border-transparent"
            >
              <option value="newest">Newest first</option>
              <option value="oldest">Oldest first</option>
              <option value="amount_high">Amount: high to low</option>
              <option value="amount_low">Amount: low to high</option>
              <option value="status">Status A-Z</option>
            </select>
          </div>
        </div>
      </div>

      {/* Activity Timeline */}
      {sortedMandates.length === 0 ? (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-12 text-center">
          <Activity className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-gray-900 mb-2">
            No Activity Found
          </h3>
          <p className="text-gray-600">
            {searchQuery || filter !== "all" || statusFilter !== "all"
              ? "Try adjusting your filters or search query."
              : "Your AI agent activity will appear here once you create Intent Mandates."}
          </p>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
          <div className="divide-y divide-gray-200">
            {sortedMandates.map((mandate, index) => (
              <ActivityTimelineItem
                key={mandate.id}
                mandate={mandate}
                isFirst={index === 0}
              />
            ))}
          </div>
        </div>
      )}

      {/* Export Option */}
      {sortedMandates.length > 0 && (
        <div className="flex justify-end">
          <button
            onClick={() => exportActivity(sortedMandates)}
            className="px-4 py-2 bg-white border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 transition-colors flex items-center space-x-2"
          >
            <Download className="w-4 h-4" />
            <span>Export Activity Log</span>
          </button>
        </div>
      )}
    </div>
  );
};

// Stat Card Component
const StatCard = ({ icon, label, value, color, subtitle }) => {
  const colors = {
    blue: "bg-blue-100 text-blue-600",
    green: "bg-green-100 text-green-600",
    yellow: "bg-yellow-100 text-yellow-600",
    red: "bg-red-100 text-red-600",
    purple: "bg-purple-100 text-purple-600",
    gray: "bg-gray-100 text-gray-600",
    orange: "bg-orange-100 text-orange-600",
  };

  return (
    <div className="bg-white rounded-lg border border-gray-200 p-4">
      <div className="flex items-center space-x-3">
        <div className={`p-2 rounded-lg ${colors[color]}`}>{icon}</div>
        <div className="flex-1">
          <p className="text-sm text-gray-600">{label}</p>
          <p className="text-2xl font-bold text-gray-900">{value}</p>
          {subtitle && <p className="text-xs text-gray-400">{subtitle}</p>}
        </div>
      </div>
    </div>
  );
};

// Activity Timeline Item Component
const ActivityTimelineItem = ({ mandate, isFirst }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const { formatDate: orgFormatDate, timezone } = useOrganization();
  const payment = mandate._payment;

  const formatDate = (dateString) => {
    // Fix timezone: backend sends UTC time without 'Z', so append it
    const dateStr = dateString.endsWith('Z') ? dateString : dateString + 'Z';
    const date = new Date(dateStr);
    const now = new Date();
    const diff = now - date;
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(diff / 3600000);
    const days = Math.floor(diff / 86400000);

    if (minutes < 1) return "Just now";
    if (minutes < 60) return `${minutes} minute${minutes > 1 ? "s" : ""} ago`;
    if (hours < 24) return `${hours} hour${hours > 1 ? "s" : ""} ago`;
    if (days < 7) return `${days} day${days > 1 ? "s" : ""} ago`;

    // Use org timezone for older dates
    return orgFormatDate(dateString);
  };

  const getStatusConfig = (status) => {
    const configs = {
      completed: {
        bg: "bg-green-100",
        text: "text-green-800",
        icon: CheckCircle,
        iconColor: "text-green-600",
        dot: "bg-green-500",
      },
      active: {
        bg: "bg-yellow-100",
        text: "text-yellow-800",
        icon: Clock,
        iconColor: "text-yellow-600",
        dot: "bg-yellow-500",
      },
      pending: {
        bg: "bg-blue-100",
        text: "text-blue-800",
        icon: Clock,
        iconColor: "text-blue-600",
        dot: "bg-blue-500",
      },
      failed: {
        bg: "bg-red-100",
        text: "text-red-800",
        icon: XCircle,
        iconColor: "text-red-600",
        dot: "bg-red-500",
      },
      expired: {
        bg: "bg-gray-100",
        text: "text-gray-800",
        icon: AlertTriangle,
        iconColor: "text-gray-600",
        dot: "bg-gray-500",
      },
      revoked: {
        bg: "bg-orange-100",
        text: "text-orange-800",
        icon: XCircle,
        iconColor: "text-orange-600",
        dot: "bg-orange-500",
      },
    };

