          {/* Expanded Payment Details (for grouped items) */}
          {payment && (
            <div className="mt-4 pt-4 border-t border-gray-200">
              <h5 className="text-sm font-semibold text-gray-900 mb-3">
                Payment Details
              </h5>
              <div className="grid grid-cols-2 gap-3 text-sm">
