            {analytics.top_spenders.slice(0, 5).map((spender, idx) => (
              <div key={spender.username} className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <span className="text-gray-500 font-medium">#{idx + 1}</span>
                  <span className="text-gray-700">{spender.name}</span>
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-gray-600">{spender.expense_count} expenses</span>
                  <span className="font-semibold text-gray-900">
                    {formatCurrency(spender.total_amount)}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Charts Row 3: Status Distribution and Top Vendors */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Status Distribution */}
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">Expense Status</h3>
          {analytics.status_distribution.length > 0 ? (
            <div>
              <ResponsiveContainer width="100%" height={250}>
                <PieChart>
                  <Pie
                    data={analytics.status_distribution}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={80}
                    fill="#8884d8"
                    dataKey="count"
                    label={({ status, count }) => `${status}: ${count}`}
                  >
                    {analytics.status_distribution.map((entry, index) => (
                      <Cell
                        key={`cell-${index}`}
                        fill={STATUS_COLORS[entry.status] || "#9CA3AF"}
                      />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
              <div className="mt-4 space-y-2">
                {analytics.status_distribution.map((status) => (
                  <div key={status.status} className="flex items-center justify-between text-sm">
                    <div className="flex items-center gap-2">
                      <div
                        className="w-3 h-3 rounded-full"
                        style={{ backgroundColor: STATUS_COLORS[status.status] || "#9CA3AF" }}
                      ></div>
                      <span className="text-gray-700">{status.status}</span>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className="text-gray-600">{status.count} expenses</span>
                      <span className="font-semibold text-gray-900">
                        {formatCurrency(status.amount)}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <p className="text-gray-500 text-center py-12">No status data available</p>
          )}
        </div>

        {/* Top Vendors */}
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">Top Vendors</h3>
          {analytics.top_vendors.length > 0 ? (
            <div className="space-y-3">
              {analytics.top_vendors.slice(0, 8).map((vendor, idx) => (
                <div
                  key={vendor.vendor}
                  className="flex items-center justify-between p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors"
                >
                  <div className="flex items-center gap-3">
                    <span className="text-gray-500 font-semibold text-sm">#{idx + 1}</span>
                    <div>
                      <p className="font-medium text-gray-900">{vendor.vendor}</p>
                      <p className="text-sm text-gray-500">{vendor.count} transactions</p>
                    </div>
                  </div>
                  <span className="font-semibold text-gray-900">
                    {formatCurrency(vendor.amount)}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 text-center py-12">No vendor data available</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default AnalyticsDashboard;

import React, { useState, useEffect } from "react";
import {
  Plus,
  Edit2,
  Trash2,
  Power,
  CheckCircle,
  XCircle,
  AlertCircle,
  AlertTriangle,
  DollarSign,
  Users,
  Calendar,
  Clock,
  Tag,
  Building,
  TrendingUp,
  TestTube,
  Save,
  X,
} from "lucide-react";
import { useToast } from "../hooks/useToast";

const EXPENSE_CATEGORIES = [
  "MEALS",
  "TRAVEL",
  "OFFICE_SUPPLIES",
  "EQUIPMENT",
  "SOFTWARE",
  "MARKETING",
  "ENTERTAINMENT",
  "PARKING",
  "FUEL",
  "SHIPPING",
  "OTHER",
];

const ApprovalPolicies = () => {
  const { success, error: showError } = useToast();
  const [policies, setPolicies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [editingPolicy, setEditingPolicy] = useState(null);
  const [testingPolicy, setTestingPolicy] = useState(null);

  // Priority mapping
  const PRIORITY_LEVELS = {
    low: 100,
    medium: 500,
    high: 900,
  };

  const getPriorityLabel = (numericPriority) => {
    if (numericPriority >= 700) return "high";
    if (numericPriority >= 300) return "medium";
    return "low";
  };

  // Form state
  const [formData, setFormData] = useState({
    name: "",
    description: "",
    priority: "medium",
    auto_approve: true,
    require_receipt: false,
    notify_on_auto_approve: true,
    max_amount_per_expense: "",
    daily_limit_per_user: "",
    monthly_limit_per_user: "",
    yearly_limit_per_user: "",
    conditions: {
      categories: [],
      vendors: [],
      exclude_vendors: [],
      min_amount: "",
    },
  });

  // Test form state
  const [testData, setTestData] = useState({
    amount: "",
    category: "", // Empty = All Categories
    vendor: "",
    has_receipt: true,
    test_limit_type: "", // "", "daily", "monthly", "yearly"
  });
  const [testResult, setTestResult] = useState(null);

  useEffect(() => {
    loadPolicies();
  }, []);

  const loadPolicies = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem("access_token");
      const response = await fetch("/api/v1/approval-policies", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!response.ok) throw new Error("Failed to load rules");

      const data = await response.json();
      setPolicies(data);
    } catch (err) {
      showError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const token = localStorage.getItem("access_token");

      // Parse numeric values for validation
      const maxPerExpense = formData.max_amount_per_expense
        ? parseFloat(formData.max_amount_per_expense)
        : null;
      const dailyLimit = formData.daily_limit_per_user
        ? parseFloat(formData.daily_limit_per_user)
        : null;
      const monthlyLimit = formData.monthly_limit_per_user
        ? parseFloat(formData.monthly_limit_per_user)
        : null;
      const yearlyLimit = formData.yearly_limit_per_user
        ? parseFloat(formData.yearly_limit_per_user)
        : null;

      // Validate limit logic
      if (maxPerExpense && dailyLimit && dailyLimit < maxPerExpense) {
        showError(
          `Daily limit ($${dailyLimit}) must be at least $${maxPerExpense} (max per expense) to allow any expenses up to the maximum amount.`
        );
        return;
      }

      if (dailyLimit && monthlyLimit && monthlyLimit < dailyLimit) {
        showError(
          `Monthly limit ($${monthlyLimit}) must be at least $${dailyLimit} (daily limit).`
        );
        return;
      }

      if (monthlyLimit && yearlyLimit && yearlyLimit < monthlyLimit) {
        showError(
          `Yearly limit ($${yearlyLimit}) must be at least $${monthlyLimit} (monthly limit).`
        );
        return;
      }

      const payload = {
        ...formData,
        priority: PRIORITY_LEVELS[formData.priority], // Convert text to numeric
        max_amount_per_expense: maxPerExpense,
        daily_limit_per_user: dailyLimit,
        monthly_limit_per_user: monthlyLimit,
        yearly_limit_per_user: yearlyLimit,
        conditions: {
          ...formData.conditions,
          min_amount: formData.conditions.min_amount
            ? parseFloat(formData.conditions.min_amount)
            : undefined,
        },
      };

      const url = editingPolicy
        ? `/api/v1/approval-policies/${editingPolicy.id}`
        : "/api/v1/approval-policies";

      const response = await fetch(url, {
        method: editingPolicy ? "PATCH" : "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) throw new Error("Failed to save rule");

      success(editingPolicy ? "Rule updated!" : "Rule created!");
      setShowCreateForm(false);
      setEditingPolicy(null);
      resetForm();
      loadPolicies();
    } catch (err) {
      showError(err.message);
    }
  };

  const handleDelete = async (policyId) => {
    if (!confirm("Are you sure you want to delete this rule?")) return;

    try {
      const token = localStorage.getItem("access_token");
      const response = await fetch(`/api/v1/approval-policies/${policyId}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!response.ok) throw new Error("Failed to delete rule");

      success("Rule deleted!");
      loadPolicies();
    } catch (err) {
      showError(err.message);
    }
  };

  const handleToggleActive = async (policy) => {
    try {
      const token = localStorage.getItem("access_token");
      const response = await fetch(`/api/v1/approval-policies/${policy.id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          is_active: !policy.is_active,
        }),
      });

      if (!response.ok) throw new Error("Failed to update rule");

      success(
        policy.is_active ? "Rule deactivated!" : "Rule activated!"
      );
      loadPolicies();
    } catch (err) {
      showError(err.message);
    }
  };

  const handleTest = async (e) => {
    e.preventDefault();

    // Validate amount before sending
    const amount = parseFloat(testData.amount);
    if (isNaN(amount) || amount <= 0) {
      showError("Please enter a valid amount greater than 0");
      return;
    }

    try {
      const token = localStorage.getItem("access_token");

      // Build payload with parsed numeric values
      const payload = {
        amount: amount,
        category: testData.category,
        vendor: testData.vendor,
        has_receipt: testData.has_receipt,
        test_limit_type: testData.test_limit_type || null,
      };

      const response = await fetch("/api/v1/approval-policies/test", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => null);
        const errorMsg = errorData?.detail || "Failed to test rules";
        throw new Error(errorMsg);
      }

      const result = await response.json();
      setTestResult(result);
    } catch (err) {
      showError(err.message);
      setTestResult(null);
    }
  };

  const resetForm = () => {
    setFormData({
      name: "",
      description: "",
      priority: "medium",
      auto_approve: true,
      require_receipt: false,
      notify_on_auto_approve: true,
      max_amount_per_expense: "",
      daily_limit_per_user: "",
      monthly_limit_per_user: "",
      yearly_limit_per_user: "",
      conditions: {
        categories: [],
        vendors: [],
        exclude_vendors: [],
        min_amount: "",
      },
    });
  };

  const startEdit = (policy) => {
    setEditingPolicy(policy);
    setFormData({
      name: policy.name,
      description: policy.description || "",
      priority: getPriorityLabel(policy.priority), // Convert numeric to text
      auto_approve: policy.auto_approve,
      require_receipt: policy.require_receipt,
      notify_on_auto_approve: policy.notify_on_auto_approve,
      max_amount_per_expense: policy.limits?.max_amount_per_expense || "",
      daily_limit_per_user: policy.limits?.daily_limit_per_user || "",
      monthly_limit_per_user: policy.limits?.monthly_limit_per_user || "",
      yearly_limit_per_user: policy.limits?.yearly_limit_per_user || "",
      conditions: policy.conditions || {
        categories: [],
        vendors: [],
        exclude_vendors: [],
        min_amount: "",
      },
    });
    setShowCreateForm(true);
  };

  const toggleCategory = (category) => {
    setFormData((prev) => ({
      ...prev,
      conditions: {
        ...prev.conditions,
        categories: prev.conditions.categories.includes(category)
          ? prev.conditions.categories.filter((c) => c !== category)
          : [...prev.conditions.categories, category],
      },
    }));
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading approval rules...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">
            Approval Rules
          </h2>
          <p className="mt-1 text-sm text-gray-500">
            Reduce your approval workload with automatic rule-based approvals
          </p>
        </div>
        <button
          onClick={() => {
            setShowCreateForm(true);
            setEditingPolicy(null);
            resetForm();
          }}
          className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700"
        >
          <Plus className="h-5 w-5 mr-2" />
          Create Rule
        </button>
      </div>

      {/* Info Banner */}
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
        <div className="flex">
          <CheckCircle className="h-5 w-5 text-blue-600 mt-0.5" />
          <div className="ml-3">
            <h3 className="text-sm font-medium text-blue-800">
              How Approval Rules Work
            </h3>
            <p className="mt-1 text-sm text-blue-700">
              <strong>Save time on routine approvals.</strong> Rules automatically approve expenses that match your conditions (amount, category, etc.).
              Rules are checked in priority order - if an expense matches a rule and stays within limits, it's instantly approved without manual review.
              All other expenses still require your approval.
            </p>
            <p className="mt-2 text-xs text-blue-600">
              💡 Example: "Auto-approve meals under $50 with receipt" - instantly approves qualifying lunch expenses
            </p>
          </div>
        </div>
      </div>

      {/* Create/Edit Form */}
      {showCreateForm && (
        <div className="bg-white rounded-lg shadow-md p-6 border border-gray-200">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-semibold text-gray-900">
              {editingPolicy ? "Edit Rule" : "Create New Approval Rule"}
            </h3>
            <button
              onClick={() => {
                setShowCreateForm(false);
                setEditingPolicy(null);
                resetForm();
              }}
              className="text-gray-400 hover:text-gray-600"
            >
              <X className="h-5 w-5" />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Basic Info */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Rule Name *
                </label>
                <input
                  type="text"
                  required
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
                  placeholder="e.g., Small Meal Expenses"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Priority
                </label>
                <select
                  value={formData.priority}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      priority: e.target.value,
                    })
                  }
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
                >
                  <option value="low">Low</option>
                  <option value="medium">Medium</option>
                  <option value="high">High</option>
                </select>
                <p className="mt-1 text-xs text-gray-500">
                  High priority rules are checked first
                </p>
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Description
              </label>
              <textarea
                value={formData.description}
                onChange={(e) =>
                  setFormData({ ...formData, description: e.target.value })
                }
                rows="2"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
                placeholder="e.g., Auto-approve small team meals to save time"
              />
            </div>

            {/* Amount Limits */}
            <div>
              <h4 className="text-sm font-semibold text-gray-900 mb-3 flex items-center">
                <DollarSign className="h-4 w-4 mr-2 text-green-600" />
                Amount Limits
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm text-gray-700 mb-2">
                    Max per expense ($)
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.max_amount_per_expense}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        max_amount_per_expense: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    placeholder="e.g., 100.00"
                  />
                </div>

                <div>
                  <label className="block text-sm text-gray-700 mb-2">
                    Min amount ($)
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.conditions.min_amount}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        conditions: {
                          ...formData.conditions,
                          min_amount: e.target.value,
                        },
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    placeholder="Optional"
                  />
                </div>
              </div>
            </div>

            {/* User Spending Limits */}
            <div>
              <h4 className="text-sm font-semibold text-gray-900 mb-3 flex items-center">
                <Users className="h-4 w-4 mr-2 text-blue-600" />
                Per-User Spending Limits
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-sm text-gray-700 mb-2">
                    Daily limit ($)
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.daily_limit_per_user}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        daily_limit_per_user: e.target.value,
                      })
                    }
                    className={`w-full px-3 py-2 border rounded-md ${
                      formData.max_amount_per_expense &&
                      formData.daily_limit_per_user &&
                      parseFloat(formData.daily_limit_per_user) <
                        parseFloat(formData.max_amount_per_expense)
                        ? "border-red-300 bg-red-50"
                        : "border-gray-300"
                    }`}
                    placeholder="Optional"
                  />
                  {formData.max_amount_per_expense &&
                    formData.daily_limit_per_user &&
                    parseFloat(formData.daily_limit_per_user) <
                      parseFloat(formData.max_amount_per_expense) && (
                      <p className="mt-1 text-xs text-red-600 flex items-center">
                        <AlertTriangle className="h-3 w-3 mr-1" />
                        Must be ≥ ${formData.max_amount_per_expense} (max per
                        expense)
                      </p>
                    )}
                </div>

                <div>
                  <label className="block text-sm text-gray-700 mb-2">
                    Monthly limit ($)
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.monthly_limit_per_user}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        monthly_limit_per_user: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    placeholder="Optional"
                  />
                </div>

                <div>
                  <label className="block text-sm text-gray-700 mb-2">
                    Yearly limit ($)
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.yearly_limit_per_user}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        yearly_limit_per_user: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border border-gray-300 rounded-md"
                    placeholder="Optional"
                  />
                </div>
              </div>
            </div>

            {/* Categories */}
            <div>
              <h4 className="text-sm font-semibold text-gray-900 mb-3 flex items-center">
                <Tag className="h-4 w-4 mr-2 text-purple-600" />
                Allowed Categories
              </h4>
              <p className="text-xs text-gray-500 mb-3">
                Leave empty to allow all categories
              </p>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                {EXPENSE_CATEGORIES.map((category) => (
                  <label
                    key={category}
                    className="flex items-center space-x-2 cursor-pointer"
                  >
                    <input
                      type="checkbox"
                      checked={formData.conditions.categories.includes(
                        category
                      )}
                      onChange={() => toggleCategory(category)}
                      className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                    />
                    <span className="text-sm text-gray-700">{category}</span>
                  </label>
                ))}
              </div>
            </div>

            {/* Options */}
            <div>
              <h4 className="text-sm font-semibold text-gray-900 mb-3">
                Options
              </h4>
              <div className="space-y-2">
                <label className="flex items-center space-x-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={formData.auto_approve}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        auto_approve: e.target.checked,
                      })
                    }
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-sm text-gray-700">
                    Auto-approve matching expenses
                  </span>
                </label>

                <label className="flex items-center space-x-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={formData.notify_on_auto_approve}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        notify_on_auto_approve: e.target.checked,
                      })
                    }
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-sm text-gray-700">
                    Notify user on auto-approval
                  </span>
                </label>
              </div>
            </div>

            {/* Actions */}
            <div className="flex items-center justify-end space-x-3 pt-4 border-t">
              <button
                type="button"
                onClick={() => {
                  setShowCreateForm(false);
                  setEditingPolicy(null);
                  resetForm();
                }}
                className="px-4 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700"
              >
                <Save className="h-4 w-4 mr-2" />
                {editingPolicy ? "Update Rule" : "Create Rule"}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Test Rules */}
      <div className="bg-white rounded-lg shadow-md p-6 border border-gray-200">
        <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
          <TestTube className="h-5 w-5 mr-2 text-orange-600" />
          Test Your Rules
        </h3>
        <p className="text-sm text-gray-600 mb-4">
          Check if a sample expense would be automatically approved by your current rules
        </p>

        <form onSubmit={handleTest} className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Amount ($)
              </label>
              <input
                type="number"
                step="0.01"
                min="0"
                required
                value={testData.amount}
                onChange={(e) =>
                  setTestData({ ...testData, amount: e.target.value })
                }
                className="w-full px-3 py-2 border border-gray-300 rounded-md"
                placeholder="50.00"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Test Limit
              </label>
              <select
                value={testData.test_limit_type}
                onChange={(e) =>
                  setTestData({ ...testData, test_limit_type: e.target.value })
                }
                className="w-full px-3 py-2 border border-gray-300 rounded-md"
              >
                <option value="">Per-expense only</option>
                <option value="daily">Daily limit</option>
                <option value="monthly">Monthly limit</option>
                <option value="yearly">Yearly limit</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Category
              </label>
              <select
                value={testData.category}
                onChange={(e) =>
                  setTestData({ ...testData, category: e.target.value })
                }
                className="w-full px-3 py-2 border border-gray-300 rounded-md"
              >
                <option value="">All Categories</option>
                {EXPENSE_CATEGORIES.map((cat) => (
                  <option key={cat} value={cat}>
                    {cat}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Vendor
              </label>
              <input
                type="text"
                value={testData.vendor}
                onChange={(e) =>
                  setTestData({ ...testData, vendor: e.target.value })
                }
                className="w-full px-3 py-2 border border-gray-300 rounded-md"
                placeholder="e.g., Amazon"
              />
            </div>
          </div>

          <div className="mt-4">
            <button
              type="submit"
              className="w-full px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-orange-600 hover:bg-orange-700"
            >
              Test
            </button>
          </div>
        </form>

        {testResult && (
          <div
            className={`mt-4 p-4 rounded-lg ${
              testResult.would_auto_approve
                ? "bg-green-50 border border-green-200"
                : "bg-yellow-50 border border-yellow-200"
            }`}
          >
            <div className="flex items-start">
              {testResult.would_auto_approve ? (
                <CheckCircle className="h-5 w-5 text-green-600 mt-0.5" />
              ) : (
                <AlertCircle className="h-5 w-5 text-yellow-600 mt-0.5" />
              )}
              <div className="ml-3">
                <h4
                  className={`text-sm font-medium ${
                    testResult.would_auto_approve
                      ? "text-green-800"
                      : "text-yellow-800"
                  }`}
                >
                  {testResult.would_auto_approve
                    ? "✓ Would Auto-Approve"
                    : `⚠ ${testResult.reason}`}
                </h4>
                {testResult.would_auto_approve && (
                  <p
                    className="mt-1 text-sm text-green-700"
                  >
                    {testResult.reason}
                  </p>
                )}
                {testResult.matching_policy && (
                  <p className="mt-2 text-xs text-gray-600">
                    Matched Rule: <strong>{testResult.matching_policy.name}</strong>
                  </p>
                )}
                {testResult.remaining_limits && (
                  <div className="mt-2 text-xs text-gray-600">
                    <strong>Remaining Limits:</strong>
                    {testResult.remaining_limits.daily_remaining && (
                      <span className="ml-2">
                        Daily: ${testResult.remaining_limits.daily_remaining}
                      </span>
                    )}
                    {testResult.remaining_limits.monthly_remaining && (
                      <span className="ml-2">
                        Monthly: ${testResult.remaining_limits.monthly_remaining}
                      </span>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Rules List */}
      <div className="bg-white rounded-lg shadow-md overflow-hidden border border-gray-200">
        <div className="px-6 py-4 border-b border-gray-200">
          <h3 className="text-lg font-semibold text-gray-900">
            Your Approval Rules ({policies.length})
          </h3>
        </div>

        {policies.length === 0 ? (
          <div className="p-12 text-center">
            <CheckCircle className="h-12 w-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">
              No approval rules yet
            </h3>
            <p className="text-gray-500 mb-4">
              Create your first rule to automatically approve routine expenses and save time
            </p>
            <button
              onClick={() => setShowCreateForm(true)}
              className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700"
            >
              <Plus className="h-5 w-5 mr-2" />
              Create Rule
            </button>
          </div>
        ) : (
          <div className="divide-y divide-gray-200">
            {policies
              .sort((a, b) => b.priority - a.priority)
              .map((policy) => (
                <div
                  key={policy.id}
                  className={`p-6 ${
                    !policy.is_active ? "bg-gray-50" : ""
                  }`}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center space-x-3">
                        <h4 className="text-lg font-medium text-gray-900">
                          {policy.name}
                        </h4>
                        <span
                          className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                            policy.is_active
                              ? "bg-green-100 text-green-800"
                              : "bg-gray-100 text-gray-800"
                          }`}
                        >
                          {policy.is_active ? "Active" : "Inactive"}
                        </span>
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                          getPriorityLabel(policy.priority) === "high"
                            ? "bg-red-100 text-red-800"
                            : getPriorityLabel(policy.priority) === "medium"
                            ? "bg-blue-100 text-blue-800"
                            : "bg-gray-100 text-gray-800"
                        }`}>
                          {getPriorityLabel(policy.priority).charAt(0).toUpperCase() + getPriorityLabel(policy.priority).slice(1)} Priority
                        </span>
                      </div>

                      {policy.description && (
                        <p className="mt-1 text-sm text-gray-600">
                          {policy.description}
                        </p>
                      )}

                      <div className="mt-3 flex flex-wrap gap-2 text-sm text-gray-600">
                        {policy.limits?.max_amount_per_expense && (
                          <span className="inline-flex items-center px-2 py-1 rounded bg-gray-100">
                            <DollarSign className="h-3 w-3 mr-1" />
                            Max: ${policy.limits.max_amount_per_expense}
                          </span>
                        )}
                        {policy.limits?.daily_limit_per_user && (
                          <span className="inline-flex items-center px-2 py-1 rounded bg-gray-100">
                            <Calendar className="h-3 w-3 mr-1" />
                            Daily: ${policy.limits.daily_limit_per_user}
                          </span>
                        )}
                        {policy.limits?.monthly_limit_per_user && (
                          <span className="inline-flex items-center px-2 py-1 rounded bg-gray-100">
                            <TrendingUp className="h-3 w-3 mr-1" />
                            Monthly: ${policy.limits.monthly_limit_per_user}
                          </span>
                        )}
                        {policy.limits?.yearly_limit_per_user && (
                          <span className="inline-flex items-center px-2 py-1 rounded bg-gray-100">
                            <TrendingUp className="h-3 w-3 mr-1" />
                            Yearly: ${policy.limits.yearly_limit_per_user}
                          </span>
                        )}
                        <span className="inline-flex items-center px-2 py-1 rounded bg-purple-100 text-purple-700">
                          <Tag className="h-3 w-3 mr-1" />
                          {policy.conditions?.categories?.length > 0
                            ? policy.conditions.categories.length === 1
                              ? policy.conditions.categories[0]
                              : `${policy.conditions.categories.length} categories: ${policy.conditions.categories.join(', ')}`
                            : "All Categories"
                          }
                        </span>
                      </div>
                    </div>

                    <div className="flex items-center space-x-2 ml-4">
                      <button
                        onClick={() => handleToggleActive(policy)}
                        className={`p-2 rounded-md ${
                          policy.is_active
                            ? "text-green-600 hover:bg-green-50"
                            : "text-gray-400 hover:bg-gray-100"
                        }`}
                        title={policy.is_active ? "Deactivate" : "Activate"}
                      >
                        <Power className="h-5 w-5" />
                      </button>
                      <button
                        onClick={() => startEdit(policy)}
                        className="p-2 text-blue-600 hover:bg-blue-50 rounded-md"
                        title="Edit"
                      >
                        <Edit2 className="h-5 w-5" />
                      </button>
                      <button
                        onClick={() => handleDelete(policy.id)}
                        className="p-2 text-red-600 hover:bg-red-50 rounded-md"
                        title="Delete"
                      >
                        <Trash2 className="h-5 w-5" />
                      </button>
                    </div>
                  </div>
                </div>
              ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default ApprovalPolicies;

import React, { useState, useRef } from "react";
import {
  Upload,
  X,
  Check,
  AlertCircle,
  Edit2,
  Save,
  Loader,
} from "lucide-react";
import { useToast } from "../hooks/useToast";

const BatchReceiptUpload = ({ onSuccess, onCancel }) => {
  const { success: showSuccess, error: showError } = useToast();
  const [files, setFiles] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [extractedData, setExtractedData] = useState([]);
  const [editingIndex, setEditingIndex] = useState(null);
  const [editData, setEditData] = useState({});
  const [creating, setCreating] = useState(false);
  const fileInputRef = useRef(null);

  const handleDragOver = (e) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();

    // Prevent adding more files if already at limit
    if (files.length >= 10) {
      showError("Maximum 10 files per batch - cannot add more files");
      return;
    }

    const droppedFiles = Array.from(e.dataTransfer.files);
    handleFiles(droppedFiles);
  };

  const handleFileSelect = (e) => {
    const selectedFiles = Array.from(e.target.files);
    handleFiles(selectedFiles);
  };

  const handleFiles = (newFiles) => {
    // Validate file types
    const validTypes = [
      "image/jpeg",
      "image/jpg",
      "image/png",
      "image/gif",
      "image/bmp",
      "image/webp",
      "application/pdf",
    ];
    const validFiles = newFiles.filter((file) => {
      if (!validTypes.includes(file.type)) {
        showError(`Invalid file type: ${file.name}`);
        return false;
      }
      if (file.size > 10 * 1024 * 1024) {
        showError(`File too large: ${file.name} (max 10MB)`);
        return false;
      }
      return true;
    });

    if (files.length + validFiles.length > 10) {
      const remaining = 10 - files.length;
      showError(
        `Cannot add ${validFiles.length} file(s). You can only add ${remaining} more file(s) (10 file maximum)`
      );
      return;
    }

    setFiles([...files, ...validFiles]);
  };

  const removeFile = (index) => {
    setFiles(files.filter((_, i) => i !== index));
    setExtractedData(extractedData.filter((_, i) => i !== index));
  };

  const handleUploadAndExtract = async () => {
    if (files.length === 0) {
      showError("Please select at least one file");
      return;
    }

    setUploading(true);

    try {
      const formData = new FormData();
      files.forEach((file) => {
        formData.append("files", file);
      });

      const token = localStorage.getItem("access_token");
      const response = await fetch("/api/v1/receipts/batch-upload", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
        },
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "Upload failed");
      }

      const data = await response.json();

      // Auto-create expenses immediately
      let successCount = 0;
      const token2 = localStorage.getItem("access_token");

      for (let i = 0; i < data.results.length; i++) {
        const result = data.results[i];
        if (!result.success) continue;

        try {
          // Use filename as vendor, default amount $1.00
          const vendor = files[i].name.replace(/\.[^/.]+$/, ""); // Remove extension
          const amount = 1.00;

          const expenseResponse = await fetch("/api/v1/receipts/create-from-extraction", {
            method: "POST",
            headers: {
              Authorization: `Bearer ${token2}`,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              vendor: vendor,
              amount: amount,
              category: "Other",
              description: "Batch upload - please review and edit",
              temp_filename: result.temp_filename,
              original_filename: files[i].name,
              content_type: result.content_type,
            }),
          });

          if (expenseResponse.ok) {
            successCount++;
          }
        } catch (err) {
          console.error(`Failed to create expense ${i}:`, err);
        }
      }

      showSuccess(`Created ${successCount} expenses successfully! Please review and edit them.`);

      // Close modal and refresh
      setTimeout(() => {
        onSuccess();
      }, 1500);

    } catch (err) {
      showError(err.message || "Failed to upload receipts");
      console.error(err);
    } finally {
      setUploading(false);
    }
  };

  const handleEdit = (index) => {
    setEditingIndex(index);
    setEditData(extractedData[index]);
  };

  const handleSaveEdit = () => {
    const updated = [...extractedData];
    updated[editingIndex] = editData;
    setExtractedData(updated);
    setEditingIndex(null);
    setEditData({});
  };

  const handleCancelEdit = () => {
    setEditingIndex(null);
    setEditData({});
  };

  const handleCreateExpense = async (index) => {
    const item = extractedData[index];

    if (!item.vendor || !item.amount) {
      showError("Vendor and amount are required");
      return;
    }

    try {
      const token = localStorage.getItem("access_token");
      const response = await fetch("/api/v1/receipts/create-from-extraction", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          vendor: item.vendor,
          amount: parseFloat(item.amount),
          category: item.category,
          description: item.description,
          temp_filename: item.tempFilename,
          original_filename: item.originalFile,
          content_type: item.contentType,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "Failed to create expense");
      }

      const data = await response.json();

      // Mark as created
      const updated = [...extractedData];
      updated[index].created = true;
      updated[index].expenseId = data.expense.id;
      setExtractedData(updated);

      showSuccess(`Expense created: ${item.vendor}`);
    } catch (err) {
      showError(err.message || "Failed to create expense");
      console.error(err);
    }
  };

  const handleCreateAll = async () => {
    setCreating(true);
    let successCount = 0;

    for (let i = 0; i < extractedData.length; i++) {
      const item = extractedData[i];
      if (item.success && !item.created) {
        try {
          await handleCreateExpense(i);
          successCount++;
        } catch (err) {
          console.error(`Failed to create expense ${i}:`, err);
        }
      }
    }

    setCreating(false);

    if (successCount > 0) {
      showSuccess(`Created ${successCount} expenses successfully`);

      // Call onSuccess after a short delay to show the success message
      setTimeout(() => {
        onSuccess();
      }, 1500);
    }
  };

  const handleClose = () => {
    // Check if any expenses were created
    const hasCreatedExpenses = extractedData.some((item) => item.created);

    if (hasCreatedExpenses) {
      // Refresh the expense list before closing
      onSuccess();
    } else {
      // Just close without refreshing
      onCancel();
    }
  };

  const categories = [
    "Travel",
    "Meals",
    "Software",
    "Office Supplies",
    "Other",
  ];

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg w-full max-w-6xl max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="sticky top-0 bg-white border-b px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="inline-flex items-center justify-center w-10 h-10 bg-teal-100 rounded-full">
              <Upload className="w-6 h-6 text-teal-600" />
            </div>
            <h2 className="text-xl font-bold text-gray-900">
              Batch Receipt Upload
            </h2>
          </div>
          <button
            onClick={handleClose}
            className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
          >
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 space-y-6">
          {/* Upload Area */}
          {extractedData.length === 0 && (
            <div>
              {/* File Counter */}
              {files.length > 0 && (
                <div className="mb-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
                  <p className="text-sm font-medium text-blue-800">
                    {files.length} / 10 files selected
                    {files.length === 10 && (
                      <span className="ml-2 text-orange-600">
                        (Maximum reached)
                      </span>
                    )}
                  </p>
                </div>
              )}

              <div
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                onClick={() => files.length < 10 && fileInputRef.current?.click()}
                className={`border-2 border-dashed rounded-lg p-12 text-center transition-colors ${
                  files.length >= 10
                    ? "border-gray-200 bg-gray-50 cursor-not-allowed opacity-60"
                    : "border-gray-300 hover:border-teal-400 hover:bg-teal-50 cursor-pointer"
                }`}
              >
                <Upload className="w-16 h-16 text-gray-400 mx-auto mb-4" />
                <p className="text-lg font-medium text-gray-700 mb-2">
                  {files.length >= 10
                    ? "Maximum 10 files reached"
                    : "Drop receipt images here or click to browse"}
                </p>
                <p className="text-sm text-gray-500">
                  Supports JPG, PNG, GIF, PDF (max 10MB per file, up to 10
                  files)
                </p>
                <input
                  ref={fileInputRef}
                  type="file"
                  multiple
                  accept="image/jpeg,image/jpg,image/png,image/gif,image/bmp,image/webp,application/pdf"
                  onChange={handleFileSelect}
                  className="hidden"
                />
              </div>

              {/* Selected Files */}
              {files.length > 0 && (
                <div className="mt-4 space-y-2">
                  <h3 className="font-medium text-gray-900">
                    Selected Files ({files.length})
                  </h3>
                  <div className="space-y-2">
                    {files.map((file, index) => (
                      <div
                        key={index}
                        className="flex items-center justify-between bg-gray-50 rounded-lg p-3"
                      >
                        <div className="flex items-center gap-3">
                          <Check className="w-5 h-5 text-green-600" />
                          <div>
                            <p className="text-sm font-medium text-gray-900">
                              {file.name}
                            </p>
                            <p className="text-xs text-gray-500">
                              {(file.size / 1024).toFixed(1)} KB
                            </p>
                          </div>
                        </div>
                        <button
                          onClick={() => removeFile(index)}
                          className="p-1 hover:bg-gray-200 rounded transition-colors"
                        >
                          <X className="w-4 h-4 text-gray-500" />
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Upload Button - PROMINENT */}
              {files.length > 0 && (
                <div className="mt-6 p-4 bg-teal-50 border-2 border-teal-200 rounded-lg">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="font-semibold text-gray-900 mb-1">
                        Ready to upload {files.length} file{files.length > 1 ? 's' : ''}
                      </p>
                      <p className="text-sm text-gray-600">
                        Expenses will be created automatically with receipts attached
                      </p>
                    </div>
                    <button
                      onClick={handleUploadAndExtract}
                      disabled={uploading}
                      className="flex items-center gap-2 px-8 py-4 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors font-bold text-lg shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {uploading ? (
                        <>
                          <Loader className="w-6 h-6 animate-spin" />
                          Creating Expenses...
                        </>
                      ) : (
                        <>
                          <Upload className="w-6 h-6" />
                          Upload & Create
                        </>
                      )}
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Extracted Data Review */}
          {extractedData.length > 0 && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-lg font-semibold text-gray-900">
                  Review Extracted Data (
                  {extractedData.filter((e) => !e.created).length} pending)
                </h3>
                <button
                  onClick={handleCreateAll}
                  disabled={
                    creating ||
                    extractedData.every((e) => e.created || !e.success)
                  }
                  className="flex items-center gap-2 px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors font-medium disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {creating ? (
                    <>
                      <Loader className="w-5 h-5 animate-spin" />
                      Creating...
                    </>
                  ) : (
                    <>
                      <Save className="w-5 h-5" />
                      Create All Expenses
                    </>
                  )}
                </button>
              </div>

              {extractedData.map((item, index) => (
                <div
                  key={index}
                  className={`border rounded-lg p-4 ${
                    item.created
                      ? "bg-green-50 border-green-200"
                      : item.success
                        ? "bg-white"
                        : "bg-red-50 border-red-200"
                  }`}
                >
                  {!item.success ? (
                    <div className="flex items-center gap-3">
                      <AlertCircle className="w-5 h-5 text-red-600" />
                      <div>
                        <p className="font-medium text-gray-900">
                          {item.originalFile}
                        </p>
                        <p className="text-sm text-red-600">{item.error}</p>
                      </div>
                    </div>
                  ) : editingIndex === index ? (
                    // Edit Mode
                    <div className="space-y-4">
                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <label className="block text-sm font-medium text-gray-700 mb-1">
                            Vendor *
