import React, { useState } from "react";
import { Lock, Eye, EyeOff, AlertCircle, CheckCircle } from "lucide-react";

const ChangePassword = ({ onClose, onSuccess }) => {
  const [formData, setFormData] = useState({
    oldPassword: "",
    newPassword: "",
    confirmPassword: "",
  });
  const [showPasswords, setShowPasswords] = useState({
    old: false,
    new: false,
    confirm: false,
  });
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess(false);

    // Validate passwords match
    if (formData.newPassword !== formData.confirmPassword) {
      setError("New passwords do not match");
      return;
    }

    // Validate password strength
    if (formData.newPassword.length < 8) {
      setError("Password must be at least 8 characters long");
      return;
    }

    setLoading(true);

    try {
      const token = localStorage.getItem("access_token");
      const API_BASE_URL = import.meta.env.VITE_API_URL || "http://localhost:8000";
      const response = await fetch(`${API_BASE_URL}/api/v1/users/me/change-password`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          old_password: formData.oldPassword,
          new_password: formData.newPassword,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.detail || "Failed to change password");
      }

      setSuccess(true);
      setTimeout(() => {
        if (onSuccess) onSuccess();
        if (onClose) onClose();
      }, 2000);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const togglePasswordVisibility = (field) => {
    setShowPasswords((prev) => ({
      ...prev,
      [field]: !prev[field],
    }));
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-8">
        <div className="text-center mb-6">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-blue-100 rounded-full mb-4">
            <Lock className="w-8 h-8 text-blue-600" />
          </div>
          <h2 className="text-2xl font-bold text-gray-800">Change Password</h2>
          <p className="text-gray-600 mt-2">Update your account password</p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3">
            <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
            <p className="text-sm text-red-800">{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-lg flex items-start gap-3">
            <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
            <p className="text-sm text-green-800">
              Password changed successfully!
            </p>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Current Password
            </label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
              <input
                type={showPasswords.old ? "text" : "password"}
                value={formData.oldPassword}
                onChange={(e) =>
                  setFormData({ ...formData, oldPassword: e.target.value })
                }
                className="w-full pl-10 pr-12 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Enter current password"
                required
                disabled={loading || success}
              />
              <button
                type="button"
                onClick={() => togglePasswordVisibility("old")}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600 focus:outline-none"
                tabIndex={-1}
              >
                {showPasswords.old ? (
                  <EyeOff className="w-5 h-5" />
                ) : (
                  <Eye className="w-5 h-5" />
                )}
              </button>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              New Password
            </label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
              <input
                type={showPasswords.new ? "text" : "password"}
                value={formData.newPassword}
                onChange={(e) =>
                  setFormData({ ...formData, newPassword: e.target.value })
                }
                className="w-full pl-10 pr-12 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Enter new password"
                required
                disabled={loading || success}
                minLength={8}
              />
              <button
                type="button"
                onClick={() => togglePasswordVisibility("new")}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600 focus:outline-none"
                tabIndex={-1}
              >
                {showPasswords.new ? (
                  <EyeOff className="w-5 h-5" />
                ) : (
                  <Eye className="w-5 h-5" />
                )}
              </button>
            </div>
            <p className="text-xs text-gray-500 mt-1">
              Must be at least 8 characters
            </p>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Confirm New Password
            </label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
              <input
                type={showPasswords.confirm ? "text" : "password"}
                value={formData.confirmPassword}
                onChange={(e) =>
                  setFormData({ ...formData, confirmPassword: e.target.value })
                }
                className="w-full pl-10 pr-12 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Confirm new password"
                required
                disabled={loading || success}
                minLength={8}
              />
              <button
                type="button"
                onClick={() => togglePasswordVisibility("confirm")}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600 focus:outline-none"
                tabIndex={-1}
              >
                {showPasswords.confirm ? (
                  <EyeOff className="w-5 h-5" />
                ) : (
                  <Eye className="w-5 h-5" />
                )}
              </button>
            </div>
          </div>

          <div className="flex gap-3 pt-4">
            <button
              type="button"
              onClick={onClose}
              disabled={loading}
              className="flex-1 bg-gray-200 text-gray-800 py-3 rounded-lg font-medium hover:bg-gray-300 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading || success}
              className="flex-1 bg-blue-600 text-white py-3 rounded-lg font-medium hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {loading
                ? "Changing..."
                : success
                  ? "Changed!"
                  : "Change Password"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default ChangePassword;

import React, { useState } from "react";
import {
  X,
  Plus,
  Trash2,
  DollarSign,
  Tag,
  Store,
  Clock,
  CheckCircle,
  AlertCircle,
  Calendar,
  Sparkles,
} from "lucide-react";
import { useToast } from "../hooks/useToast";
import { useOrganization } from "../contexts/OrganizationContext";

const ConstraintBuilder = ({ onClose, onSuccess }) => {
  const { success, error: showError } = useToast();
  const { timezone } = useOrganization();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [step, setStep] = useState(1); // 1: Basic, 2: Advanced, 3: Review

  // Default expiration: 30 days from now
  const expirationPresets = [
    { label: "24 hours", hours: 24 },
    { label: "7 days", hours: 7 * 24 },
    { label: "30 days", hours: 30 * 24 },
    { label: "90 days", hours: 90 * 24 },
    { label: "Custom", hours: null },
  ];

  const getDateFromHours = (hours) => {
    const date = new Date();
    date.setHours(date.getHours() + hours);
    return date.toISOString().slice(0, 16);
  };

  const [formData, setFormData] = useState({
    maxAmount: "",
    monthlyLimit: "",
    categories: [],
    merchants: [],
    recurring: "",
    expirationPreset: 30 * 24, // default: 30 days
    expirationDateTime: getDateFromHours(30 * 24),
  });

  const [categoryInput, setCategoryInput] = useState("");
  const [merchantInput, setMerchantInput] = useState("");

  // Predefined categories for quick selection (backend format)
  const predefinedCategories = [
    { value: "OFFICE_SUPPLIES", label: "Office Supplies" },
    { value: "SOFTWARE", label: "Software" },
    { value: "TRAVEL", label: "Travel" },
    { value: "MEALS", label: "Meals" },
    { value: "COFFEE", label: "Coffee" },
    { value: "ENTERTAINMENT", label: "Entertainment" },
    { value: "UTILITIES", label: "Utilities" },
    { value: "MARKETING", label: "Marketing" },
    { value: "HARDWARE", label: "Hardware" },
    { value: "PROFESSIONAL_SERVICES", label: "Professional Services" },
    { value: "OTHER", label: "Other" },
  ];

  const recurringOptions = [
    { value: "", label: "One-time" },
    { value: "daily", label: "Daily" },
    { value: "weekly", label: "Weekly" },
    { value: "monthly", label: "Monthly" },
    { value: "quarterly", label: "Quarterly" },
  ];

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    // Validate required fields
    if (!formData.maxAmount || parseFloat(formData.maxAmount) <= 0) {
      setError("Maximum Amount is required and must be greater than zero.");
      setLoading(false);
      return;
    }
    if (!formData.monthlyLimit || parseFloat(formData.monthlyLimit) <= 0) {
      setError("Monthly Spending Limit is required and must be greater than zero.");
      setLoading(false);
      return;
    }

    // Build constraints object
    const constraints = {};
    constraints.max_amount = parseFloat(formData.maxAmount);
    constraints.monthly_limit = parseFloat(formData.monthlyLimit);

    if (formData.categories && formData.categories.length > 0) {
      constraints.categories = formData.categories;
    }

    if (formData.merchants && formData.merchants.length > 0) {
      constraints.merchants = formData.merchants;
    }

    if (formData.recurring) {
      constraints.recurring = formData.recurring;
    }

    try {
      // Calculate hours from the selected datetime
      const expirationDate = new Date(formData.expirationDateTime);
      const now = new Date();
      const hoursUntilExpiration = Math.max(1, Math.ceil((expirationDate - now) / (1000 * 60 * 60)));

      const response = await fetch("/api/ap2/intent-mandate", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.getItem("access_token")}`,
        },
        body: JSON.stringify({
          constraints,
          expiration_hours: hoursUntilExpiration,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const detail = errorData.detail || "Failed to create Intent Mandate";
        throw new Error(detail);
      }

      const result = await response.json();
      onSuccess(result);
    } catch (err) {
      console.error(err);
      showError(err.message || "Failed to create Intent Mandate. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const addCategory = (category) => {
    if (category && !formData.categories.includes(category)) {
      setFormData({
        ...formData,
        categories: [...formData.categories, category],
      });
      setCategoryInput("");
    }
  };

  const removeCategory = (category) => {
    setFormData({
      ...formData,
      categories: formData.categories.filter((c) => c !== category),
    });
  };

  const addMerchant = () => {
    if (
      merchantInput.trim() &&
      !formData.merchants.includes(merchantInput.trim())
    ) {
      setFormData({
        ...formData,
        merchants: [...formData.merchants, merchantInput.trim()],
      });
      setMerchantInput("");
    }
  };

  const removeMerchant = (merchant) => {
    setFormData({
      ...formData,
      merchants: formData.merchants.filter((m) => m !== merchant),
    });
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl shadow-2xl max-w-3xl w-full max-h-[90vh] overflow-hidden">
        {/* Header */}
        <div className="bg-gradient-to-r from-purple-600 to-indigo-600 text-white px-6 py-4 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-white/10 rounded-lg backdrop-blur-sm">
              <Sparkles className="w-6 h-6" />
            </div>
            <div>
              <h2 className="text-xl font-bold">Create Reusable Authorization</h2>
              <p className="text-purple-100 text-sm">Step {step} of 3</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-white/10 rounded-lg transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Progress Steps */}
        <div className="px-6 py-4 border-b border-gray-200">
          <div className="flex items-center justify-between">
            {[
              { num: 1, label: "Basic Settings" },
              { num: 2, label: "Advanced Rules" },
              { num: 3, label: "Review & Create" },
            ].map((s, idx) => (
              <React.Fragment key={s.num}>
                <div className="flex items-center space-x-2">
                  <div
                    className={`w-8 h-8 rounded-full flex items-center justify-center font-semibold ${
                      step >= s.num
                        ? "bg-purple-600 text-white"
                        : "bg-gray-200 text-gray-600"
                    }`}
                  >
                    {step > s.num ? <CheckCircle className="w-5 h-5" /> : s.num}
                  </div>
                  <span
                    className={`text-sm font-medium ${
                      step >= s.num ? "text-gray-900" : "text-gray-500"
                    }`}
                  >
                    {s.label}
                  </span>
                </div>
                {idx < 2 && (
                  <div
                    className={`flex-1 h-1 mx-4 rounded ${
                      step > s.num ? "bg-purple-600" : "bg-gray-200"
                    }`}
                  />
                )}
              </React.Fragment>
            ))}
          </div>
        </div>

        {/* Form Content */}
        <form
          onSubmit={handleSubmit}
          className="p-6 overflow-y-auto max-h-[calc(90vh-240px)]"
        >
          {/* Step 1: Basic Settings */}
          {step === 1 && (
            <div className="space-y-6">
              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-4">
                  Basic Settings
                </h3>
                <p className="text-sm text-gray-600 mb-6">
                  Set the fundamental constraints for what your AI agent can do.
                </p>
              </div>

              {/* Max Amount */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  <DollarSign className="w-4 h-4 inline mr-1" />
                  Maximum Amount <span className="text-red-500">*</span>
                </label>
                <input
                  type="number"
                  step="0.01"
                  min="0.01"
                  required
                  value={formData.maxAmount}
                  onChange={(e) =>
                    setFormData({ ...formData, maxAmount: e.target.value })
                  }
                  placeholder="e.g., 1000.00"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-600 focus:border-transparent"
                />
                <p className="text-xs text-gray-500 mt-1">
                  Maximum amount per transaction the agent can process.
                </p>
              </div>

              {/* Monthly Limit */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  <DollarSign className="w-4 h-4 inline mr-1" />
                  Monthly Spending Limit <span className="text-red-500">*</span>
                </label>
                <input
                  type="number"
                  step="0.01"
                  min="0.01"
                  required
                  value={formData.monthlyLimit}
                  onChange={(e) =>
                    setFormData({ ...formData, monthlyLimit: e.target.value })
                  }
                  placeholder="e.g., 5000.00"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-600 focus:border-transparent"
                />
                <p className="text-xs text-gray-500 mt-1">
                  Total spending allowed per month. Must be &ge; max amount.
                </p>
              </div>

              {/* Expiration */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  <Calendar className="w-4 h-4 inline mr-1" />
                  Expiration
                </label>
                <div className="flex flex-wrap gap-2 mb-3">
                  {expirationPresets.map((preset) => (
                    <button
                      key={preset.label}
                      type="button"
                      onClick={() => {
                        if (preset.hours === null) {
                          setFormData({ ...formData, expirationPreset: null });
                        } else {
                          setFormData({
                            ...formData,
                            expirationPreset: preset.hours,
                            expirationDateTime: getDateFromHours(preset.hours),
                          });
                        }
                      }}
                      className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors border ${
                        formData.expirationPreset === preset.hours
                          ? "bg-purple-600 text-white border-purple-600"
                          : "bg-white text-gray-700 border-gray-300 hover:bg-gray-50"
                      }`}
                    >
                      {preset.label}
                    </button>
                  ))}
                </div>
                {formData.expirationPreset === null && (
                  <input
                    type="datetime-local"
                    value={formData.expirationDateTime}
                    min={new Date().toISOString().slice(0, 16)}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        expirationDateTime: e.target.value,
                      })
                    }
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-600 focus:border-transparent"
                  />
                )}
                <p className="text-xs text-gray-500 mt-1">
                  Authorization will automatically expire after the selected duration.
                </p>
              </div>

            </div>
          )}

          {/* Step 2: Advanced Rules */}
          {step === 2 && (
            <div className="space-y-6">
              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-4">
                  Advanced Rules
                </h3>
                <p className="text-sm text-gray-600 mb-6">
                  Select at least one category to restrict the agent's spending scope. Merchants are optional.
                </p>
              </div>

              {/* Categories */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  <Tag className="w-4 h-4 inline mr-1" />
                  Allowed Categories
                </label>

                {/* Predefined Categories */}
                <div className="flex flex-wrap gap-2 mb-3">
                  {predefinedCategories.map((cat) => (
                    <button
                      key={cat.value}
                      type="button"
                      onClick={() => addCategory(cat.value)}
                      disabled={formData.categories.includes(cat.value)}
                      className={`px-3 py-1 rounded-full text-sm font-medium transition-colors ${
                        formData.categories.includes(cat.value)
                          ? "bg-purple-100 text-purple-700"
                          : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                      }`}
                    >
                      {formData.categories.includes(cat.value) ? (
                        <CheckCircle className="w-3 h-3 inline mr-1" />
                      ) : (
                        <Plus className="w-3 h-3 inline mr-1" />
                      )}
                      {cat.label}
                    </button>
                  ))}
                </div>

                {/* Custom Category Input */}
                <div className="flex space-x-2">
                  <input
                    type="text"
                    value={categoryInput}
                    onChange={(e) => setCategoryInput(e.target.value)}
                    onKeyPress={(e) =>
                      e.key === "Enter" &&
                      (e.preventDefault(), addCategory(categoryInput.toUpperCase().replace(/\s+/g, "_")))
                    }
                    placeholder="Or type custom category..."
                    className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-600 focus:border-transparent"
                  />
                  <button
                    type="button"
                    onClick={() => addCategory(categoryInput.toUpperCase().replace(/\s+/g, "_"))}
                    className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors"
                  >
                    Add
                  </button>
                </div>

                {/* Selected Categories */}
                {formData.categories.length > 0 && (
                  <div className="mt-3 flex flex-wrap gap-2">
                    {formData.categories.map((cat) => (
                      <span
                        key={cat}
                        className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-purple-100 text-purple-800"
                      >
                        {cat}
                        <button
                          type="button"
                          onClick={() => removeCategory(cat)}
                          className="ml-2 hover:text-purple-900"
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </span>
                    ))}
                  </div>
                )}

                <p className="text-xs text-gray-500 mt-2">
                  Agent will only process expenses in selected categories.
                </p>
              </div>

              {/* Merchants */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  <Store className="w-4 h-4 inline mr-1" />
                  Allowed Merchants (Optional)
                </label>

                <div className="flex space-x-2 mb-3">
                  <input
                    type="text"
                    value={merchantInput}
                    onChange={(e) => setMerchantInput(e.target.value)}
                    onKeyPress={(e) =>
                      e.key === "Enter" && (e.preventDefault(), addMerchant())
                    }
                    placeholder="e.g., Amazon, Starbucks, Uber..."
                    className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-600 focus:border-transparent"
                  />
                  <button
                    type="button"
                    onClick={addMerchant}
                    className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors"
                  >
                    Add
                  </button>
                </div>

                {formData.merchants.length > 0 && (
                  <div className="flex flex-wrap gap-2">
                    {formData.merchants.map((merchant) => (
                      <span
                        key={merchant}
                        className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-blue-100 text-blue-800"
                      >
                        {merchant}
                        <button
                          type="button"
                          onClick={() => removeMerchant(merchant)}
                          className="ml-2 hover:text-blue-900"
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </span>
                    ))}
                  </div>
                )}

                <p className="text-xs text-gray-500 mt-2">
                  Leave empty to allow all merchants.
                </p>
              </div>

              {/* Recurring */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  <Clock className="w-4 h-4 inline mr-1" />
                  Recurring Schedule
                </label>
                <select
                  value={formData.recurring}
                  onChange={(e) =>
                    setFormData({ ...formData, recurring: e.target.value })
                  }
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-600 focus:border-transparent"
                >
                  {recurringOptions.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
                <p className="text-xs text-gray-500 mt-1">
                  Set if this mandate should handle recurring expenses
                  automatically.
                </p>
              </div>
            </div>
          )}

          {/* Step 3: Review */}
          {step === 3 && (
            <div className="space-y-6">
              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-4">
                  Review & Create
                </h3>
                <p className="text-sm text-gray-600 mb-6">
                  Review your Intent Mandate settings before creating.
                </p>
              </div>

              <div className="bg-gray-50 rounded-lg p-6 space-y-4">
                <ReviewItem
                  label="Maximum Amount"
                  value={
                    formData.maxAmount
                      ? `$${parseFloat(formData.maxAmount).toFixed(2)}`
                      : "No limit"
                  }
                  icon={<DollarSign className="w-5 h-5 text-green-600" />}
                />

                <ReviewItem
                  label="Monthly Limit"
                  value={
                    formData.monthlyLimit
                      ? `$${parseFloat(formData.monthlyLimit).toFixed(2)}`
                      : "No limit"
                  }
                  icon={<DollarSign className="w-5 h-5 text-orange-600" />}
                />

                <ReviewItem
                  label={`Expires On (${timezone})`}
                  value={new Date(formData.expirationDateTime).toLocaleString("en-US", {
                    weekday: "short",
                    year: "numeric",
                    month: "short",
                    day: "numeric",
                    hour: "numeric",
                    minute: "2-digit",
                    timeZone: timezone,
                    timeZoneName: "short",
                  })}
                  icon={<Calendar className="w-5 h-5 text-blue-600" />}
                />

                {formData.categories.length > 0 && (
                  <ReviewItem
                    label="Allowed Categories"
                    value={formData.categories.join(", ")}
                    icon={<Tag className="w-5 h-5 text-purple-600" />}
                  />
                )}

                {formData.merchants.length > 0 && (
                  <ReviewItem
                    label="Allowed Merchants"
                    value={formData.merchants.join(", ")}
                    icon={<Store className="w-5 h-5 text-indigo-600" />}
                  />
                )}

                {formData.recurring && (
                  <ReviewItem
                    label="Recurring Schedule"
                    value={
                      recurringOptions.find(
                        (o) => o.value === formData.recurring,
                      )?.label
                    }
                    icon={<Clock className="w-5 h-5 text-orange-600" />}
                  />
                )}
              </div>

              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 flex items-start space-x-3">
                <AlertCircle className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" />
                <div className="text-sm text-blue-900">
                  <p className="font-medium mb-1">AP2 Protocol Security</p>
                  <p className="text-blue-800">
                    Your Intent Mandate will be cryptographically signed and
                    stored with a complete audit trail. All expenses processed
                    under this mandate will be traceable and compliant.
                  </p>
                </div>
              </div>
            </div>
          )}
        </form>

        {/* Validation Error */}
        {error && (
          <div className="mx-6 mb-2 p-3 bg-red-50 border border-red-200 rounded-lg text-sm text-red-700">
            {error}
          </div>
        )}

        {/* Footer Actions */}
        <div className="px-6 py-4 bg-gray-50 border-t border-gray-200 flex items-center justify-between">
          <div>
            {step > 1 && (
              <button
                type="button"
                onClick={() => setStep(step - 1)}
                className="px-4 py-2 text-gray-700 hover:bg-gray-100 rounded-lg transition-colors font-medium"
              >
                Back
              </button>
            )}
          </div>

          <div className="flex items-center space-x-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-gray-700 hover:bg-gray-100 rounded-lg transition-colors font-medium"
            >
              Cancel
            </button>

            {step < 3 ? (
              <button
                type="button"
                onClick={() => {
                  if (step === 1) {
                    if (!formData.maxAmount || parseFloat(formData.maxAmount) <= 0) {
                      setError("Maximum Amount is required.");
                      return;
                    }
                    if (!formData.monthlyLimit || parseFloat(formData.monthlyLimit) <= 0) {
                      setError("Monthly Spending Limit is required.");
                      return;
                    }
                    if (parseFloat(formData.monthlyLimit) < parseFloat(formData.maxAmount)) {
                      setError("Monthly Spending Limit must be greater than or equal to Maximum Amount.");
                      return;
                    }
                    setError("");
                  }
                  if (step === 2) {
                    if (formData.categories.length === 0) {
                      setError("At least one category is required.");
                      return;
                    }
                    setError("");
                  }
                  setStep(step + 1);
                }}
                className="px-6 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors font-medium"
              >
                Next
              </button>
            ) : (
              <button
                type="button"
                onClick={handleSubmit}
                disabled={loading}
                className="px-6 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors font-medium disabled:opacity-50 disabled:cursor-not-allowed flex items-center space-x-2"
              >
                {loading ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                    <span>Creating...</span>
                  </>
                ) : (
                  <>
                    <CheckCircle className="w-5 h-5" />
                    <span>Create Mandate</span>
                  </>
                )}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

// Review Item Component
