                  />
                </div>

                <div>
                  <label
                    htmlFor="expense-description"
                    className="block text-sm font-medium text-gray-700 mb-1"
                  >
                    Description <span className="text-red-600">*</span>
                  </label>
                  <textarea
                    id="expense-description"
                    value={newExpense.description}
                    onChange={(e) =>
                      setNewExpense({
                        ...newExpense,
                        description: e.target.value,
                      })
                    }
                    className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                    rows="3"
                    placeholder="Expense description"
                    required
                  />
                </div>
              </div>

              <div className="flex gap-3 mt-6">
                <button
                  onClick={() => setShowExpenseForm(false)}
                  className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  onClick={handleExpenseSubmit}
                  disabled={isSubmittingExpense}
                  className={`flex-1 px-4 py-2 ${theme.colors.button} text-white rounded-lg disabled:opacity-50 disabled:cursor-not-allowed`}
                >
                  {isSubmittingExpense ? "Submitting..." : "Submit"}
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Recurring Expenses Tab */}
        {activeTab === "recurring-expenses" && <RecurringExpenses />}

        {/* AP2 Automation Tab - AP2 Intent Mandates & Agent Protocol */}
        {activeTab === "ai-assistant" && <AIAssistant />}

        {/* Expense List */}
        {(activeTab === "active" || activeTab === "history") && (
          <div className="bg-white rounded-lg shadow-lg p-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-semibold text-gray-800">
                {activeTab === "active" ? "Active Expenses" : "Expense History"}
              </h2>
              {currentExpenses.length > 0 && (
                <span className="text-sm text-gray-600">
                  {currentExpenses.length} expense
                  {currentExpenses.length !== 1 ? "s" : ""}
                </span>
              )}
            </div>

            {/* Sort Controls */}
            {currentExpenses.length > 0 && (
              <div className="flex items-center gap-2 mb-4 pb-4 border-b">
                <span className="text-sm font-medium text-gray-700">
                  Sort by:
                </span>
                <button
                  onClick={() => handleSort("date")}
                  className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
                    sortField === "date"
                      ? `${theme.colors.badge}`
                      : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                  }`}
                >
                  Date
                  {sortField === "date" &&
                    (sortDirection === "asc" ? (
                      <ArrowUp className="w-4 h-4" />
                    ) : (
                      <ArrowDown className="w-4 h-4" />
                    ))}
                </button>
                <button
                  onClick={() => handleSort("amount")}
                  className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
                    sortField === "amount"
                      ? `${theme.colors.badge}`
                      : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                  }`}
                >
                  Amount
                  {sortField === "amount" &&
                    (sortDirection === "asc" ? (
                      <ArrowUp className="w-4 h-4" />
                    ) : (
                      <ArrowDown className="w-4 h-4" />
                    ))}
                </button>
                <button
                  onClick={() => handleSort("category")}
                  className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
                    sortField === "category"
                      ? `${theme.colors.badge}`
                      : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                  }`}
                >
                  Category
                  {sortField === "category" &&
                    (sortDirection === "asc" ? (
                      <ArrowUp className="w-4 h-4" />
                    ) : (
                      <ArrowDown className="w-4 h-4" />
                    ))}
                </button>
              </div>
            )}

            {loading ? (
              <div className="flex items-center justify-center py-12">
                <div className="text-center">
                  <div
                    className={`animate-spin rounded-full h-8 w-8 border-b-2 border-${theme.colors.primary} mx-auto mb-2`}
                  ></div>
                  <p className="text-gray-600 text-sm">Loading expenses...</p>
                </div>
              </div>
            ) : currentExpenses.length === 0 ? (
              <div className="text-center py-12">
                {activeTab === "active" ? (
                  <>
                    <CheckCircle className="w-16 h-16 text-green-300 mx-auto mb-4" />
                    <p className="text-gray-500 text-lg font-medium">
                      All caught up!
                    </p>
                    <p className="text-gray-600 text-sm mt-2">
                      No pending expenses at the moment.
                    </p>
                  </>
                ) : (
                  <>
                    <Receipt className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                    <p className="text-gray-500">
                      No expenses match the current filter.
                    </p>
                  </>
                )}
              </div>
            ) : (
              <div className="overflow-x-auto max-h-[300px] overflow-y-auto">
                <table className="w-full">
                  <thead>
                    <tr className="border-b-2 border-gray-200">
                      <th className="text-center py-3 px-2 text-sm font-semibold text-gray-700 w-12">
                        #
                      </th>
                      <th className="text-left py-3 px-4 text-sm font-semibold text-gray-700">
                        ID
                      </th>
                      <th className="text-left py-3 px-4 text-sm font-semibold text-gray-700">
                        Date
                      </th>
                      <th className="text-left py-3 px-4 text-sm font-semibold text-gray-700">
                        Category
                      </th>
                      <th className="text-left py-3 px-4 text-sm font-semibold text-gray-700">
                        Vendor
                      </th>
                      <th className="text-left py-3 px-4 text-sm font-semibold text-gray-700">
                        Description
                      </th>
                      <th className="text-right py-3 px-4 text-sm font-semibold text-gray-700">
                        Amount
                      </th>
                      <th className="text-center py-3 px-4 text-sm font-semibold text-gray-700">
                        Status
                      </th>
                      <th className="text-center py-3 px-4 text-sm font-semibold text-gray-700">
                        Actions
                      </th>
                    </tr>
                  </thead>
