                    {currentExpenses.map((expense, index) => (
                      <React.Fragment key={expense.id}>
                        <tr
                          className={`border-b border-gray-100 hover:bg-gray-50 transition-colors ${expense._optimistic ? "opacity-60" : ""}`}
                        >
                          <td className="py-3 px-2 text-center text-sm font-medium text-gray-500">
                            {(currentPage - 1) * itemsPerPage + index + 1}
                          </td>
                          <td className="py-3 px-4">
                            <div className="flex items-center gap-2">
                              <button
                                onClick={() => handleCopyExpenseId(expense.id)}
                                className="p-1 hover:bg-gray-200 rounded transition-colors flex-shrink-0"
                                title="Copy expense ID"
                              >
                                {copiedExpenseId === expense.id ? (
                                  <Check className="w-3.5 h-3.5 text-green-700" />
                                ) : (
                                  <Copy className="w-3.5 h-3.5 text-gray-600" />
                                )}
                              </button>
                              <span
                                className="text-sm font-medium text-gray-800 truncate max-w-[120px]"
                                title={expense.id}
                              >
                                {expense.id.substring(0, 8)}...
                              </span>
                              {expense.receipt_count > 0 && (
                                <button
                                  onClick={() => {
                                    setSelectedExpense(expense);
                                    setShowReceiptList(true);
                                  }}
                                  className="text-xs px-1.5 py-0.5 rounded bg-green-100 text-green-800 flex items-center gap-1 hover:bg-green-200 transition-colors cursor-pointer flex-shrink-0"
                                  title="Click to view receipt details"
                                >
                                  <Receipt className="w-3 h-3" />
                                  {expense.receipt_count}
                                </button>
                              )}
                            </div>
                          </td>
                          <td className="py-3 px-4 text-sm text-gray-600 whitespace-nowrap">
                            {formatDate(expense.date)}
                          </td>
                          <td className="py-3 px-4 text-sm text-gray-700">
                            {expense.category}
                          </td>
                          <td className="py-3 px-4 text-sm text-gray-700">
                            {expense.vendor}
                          </td>
                          <td className="py-3 px-4 text-sm text-gray-600 max-w-[250px]">
                            <div
                              className="truncate"
                              title={expense.description}
                            >
                              {expense.description}
                            </div>
                          </td>
                          <td className="py-3 px-4 text-right text-sm font-semibold text-gray-800 whitespace-nowrap">
                            ${formatCurrency(expense.amount)}
                          </td>
                          <td className="py-3 px-4 text-center">
                            {getStatusBadge(expense.status)}
                            {getAutoApprovalBadge(expense)}
                          </td>
                          <td className="py-3 px-4">
                            {expense.status?.toLowerCase() === "pending" &&
                              !expense._optimistic && (
                                <div className="flex gap-1 justify-center">
                                  <button
                                    onClick={() => {
                                      setSelectedExpense(expense);
                                      setShowExpenseEdit(true);
                                    }}
                                    className="p-1.5 bg-blue-100 text-blue-700 rounded hover:bg-blue-200 transition-colors"
                                    title="Edit this expense"
                                  >
                                    <Edit2 className="w-4 h-4" />
                                  </button>
                                  <button
                                    onClick={() => {
                                      setSelectedExpense(expense);
                                      setShowReceiptUpload(true);
                                    }}
                                    className={`p-1.5 ${theme.colors.badge} rounded hover:bg-${theme.colors.primaryLight} transition-colors`}
                                    title="Upload receipt"
                                  >
                                    <Upload className="w-4 h-4" />
                                  </button>
                                  <button
                                    onClick={() =>
                                      handleWithdrawExpense(expense)
                                    }
                                    className="p-1.5 bg-red-100 text-red-700 rounded hover:bg-red-200 transition-colors"
                                    title="Withdraw this expense"
                                  >
                                    <Trash2 className="w-4 h-4" />
                                  </button>
                                </div>
                              )}
                          </td>
                        </tr>
                        {/* Transaction ID row */}
                        {expense.transaction_id && (
                          <tr className="border-b border-gray-100">
                            <td colSpan="8" className="py-2 px-4 bg-green-50">
                              <div className="flex items-center gap-2">
                                <p className="text-xs text-green-700 font-mono">
                                  <span className="font-semibold">
                                    Transaction ID:
                                  </span>{" "}
                                  {expense.transaction_id}
                                </p>
                                <button
                                  onClick={() =>
                                    handleCopyTransactionId(
                                      expense.transaction_id,
                                    )
                                  }
                                  className="p-1 hover:bg-green-100 rounded transition-colors"
                                  title="Copy transaction ID"
                                >
                                  {copiedTxId === expense.transaction_id ? (
                                    <Check className="w-3.5 h-3.5 text-green-700" />
                                  ) : (
                                    <Copy className="w-3.5 h-3.5 text-green-600" />
                                  )}
                                </button>
                              </div>
                            </td>
                          </tr>
                        )}
                        {/* Rejection reason row */}
                        {expense.status?.toLowerCase() === "rejected" &&
                          expense.rejection_reason && (
                            <tr className="border-b border-gray-100">
                              <td colSpan="8" className="py-2 px-4 bg-red-50">
                                <p className="text-xs text-red-700">
                                  <span className="font-semibold">
                                    Rejection Reason:
                                  </span>{" "}
                                  {expense.rejection_reason}
                                </p>
                              </td>
                            </tr>
                          )}
                        {/* AP2 Auto-Approval detail row */}
                        {expense.auto_approved_via === "intent_mandate" && (
                          <tr className="border-b border-gray-100">
                            <td colSpan="9" className="py-2 px-4 bg-green-50">
                              <div className="flex items-center gap-3">
                                <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                                  <CheckCircle className="w-3 h-3 mr-1" />
                                  AI Auto-Approved
                                </span>
                                <span className="text-xs text-green-700">
                                  Approved automatically via Intent Mandate
                                </span>
                                {expense.intent_mandate_id && (
                                  <span className="text-xs text-green-600 font-mono">
                                    Mandate: {expense.intent_mandate_id.substring(0, 12)}...
                                  </span>
                                )}
                              </div>
                            </td>
                          </tr>
                        )}
                      </React.Fragment>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

            {/* Pagination for Tabs with Many Items */}
            {shouldPaginate && totalPages > 1 && (
              <div className="mt-6 flex items-center justify-between px-4 py-3 bg-white rounded-lg shadow">
                <div className="flex items-center gap-2 text-sm text-gray-600">
                  <span>
                    Showing {(currentPage - 1) * itemsPerPage + 1} to{" "}
                    {Math.min(
                      currentPage * itemsPerPage,
                      sortedExpenses.length,
                    )}{" "}
                    of {sortedExpenses.length} expenses
                  </span>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={() =>
                      setCurrentPage((prev) => Math.max(1, prev - 1))
                    }
                    disabled={currentPage === 1}
                    className="px-3 py-1 text-sm border border-gray-300 rounded hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Previous
                  </button>
                  {[...Array(totalPages)].map((_, idx) => {
                    const pageNum = idx + 1;
                    // Show first, last, current, and adjacent pages
                    if (
                      pageNum === 1 ||
                      pageNum === totalPages ||
                      Math.abs(pageNum - currentPage) <= 1
                    ) {
                      return (
                        <button
                          key={pageNum}
                          onClick={() => setCurrentPage(pageNum)}
                          className={`px-3 py-1 text-sm border rounded ${
                            currentPage === pageNum
                              ? "bg-blue-600 text-white border-blue-600"
                              : "border-gray-300 hover:bg-gray-50"
                          }`}
                        >
                          {pageNum}
                        </button>
                      );
                    } else if (Math.abs(pageNum - currentPage) === 2) {
                      return (
                        <span key={pageNum} className="px-2 text-gray-500">
                          ...
                        </span>
                      );
                    }
                    return null;
                  })}
                  <button
                    onClick={() =>
                      setCurrentPage((prev) => Math.min(totalPages, prev + 1))
                    }
                    disabled={currentPage === totalPages}
                    className="px-3 py-1 text-sm border border-gray-300 rounded hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Next
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Change Password Modal */}
        {showChangePassword && (
          <ChangePassword
            onClose={() => setShowChangePassword(false)}
            onSuccess={() => {
              success("Password changed successfully!");
              setShowChangePassword(false);
            }}
          />
        )}

        {/* Receipt Upload Modal */}
        {showReceiptUpload && selectedExpense && (
          <ReceiptUpload
            expenseId={selectedExpense.id}
            onSuccess={async (data) => {
              success("Receipt uploaded successfully!");
              setShowReceiptUpload(false);
              setSelectedExpense(null);
              // Refresh expense data to get updated receipt count
              try {
                const report = await expenseAPI.getExpenseReport(user?.id);
                if (report.expenses && Array.isArray(report.expenses)) {
                  setExpenses(report.expenses);
                }
              } catch (err) {
                console.error("Error refreshing expenses:", err);
              }
            }}
            onCancel={() => {
              setShowReceiptUpload(false);
              setSelectedExpense(null);
            }}
          />
        )}

        {/* Expense Edit Modal */}
        {showExpenseEdit && selectedExpense && (
          <ExpenseEdit
            expense={selectedExpense}
            currentUser={user}
            onSuccess={(updatedExpense) => {
              success("Expense updated successfully!");
              setShowExpenseEdit(false);
              setSelectedExpense(null);
              // Update the expense in the list
              setExpenses((prev) =>
                prev.map((e) =>
                  e.id === updatedExpense.id ? updatedExpense : e,
                ),
              );
            }}
            onCancel={() => {
              setShowExpenseEdit(false);
              setSelectedExpense(null);
            }}
          />
        )}

        {/* Export Modal */}
        {showExport && (
          <ExpenseExport
            expenses={expenses}
            onClose={() => setShowExport(false)}
          />
        )}

        {/* Receipt List Modal */}
        {showReceiptList && selectedExpense && (
          <ReceiptList
            receipts={selectedExpense.receipts || []}
            onClose={() => {
              setShowReceiptList(false);
              setSelectedExpense(null);
            }}
          />
        )}

        {/* Batch Receipt Upload Modal */}
        {showBatchUpload && (
          <BatchReceiptUpload
            onSuccess={() => {
              setShowBatchUpload(false);
              // Refresh expenses after successful batch upload
              const fetchExpenses = async () => {
                try {
                  const report = await expenseAPI.getExpenseReport(user?.id);
                  if (report.expenses && Array.isArray(report.expenses)) {
                    setExpenses(report.expenses);
                  }
                } catch (err) {
                  console.error("Error fetching expenses:", err);
                }
              };
              fetchExpenses();
            }}
            onCancel={() => setShowBatchUpload(false)}
          />
        )}
      </div>
    </div>
  );
};

export default EmployeeDashboard;

import React from "react";
import { AlertCircle } from "lucide-react";

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    console.error("Error caught by boundary:", error, errorInfo);
    this.setState({
      error,
      errorInfo,
    });
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-gradient-to-br from-red-50 to-orange-100 flex items-center justify-center p-6">
          <div className="bg-white rounded-lg shadow-lg p-8 max-w-lg w-full">
            <div className="flex items-center gap-3 mb-4">
              <AlertCircle className="w-10 h-10 text-red-600" />
              <h1 className="text-2xl font-bold text-gray-800">
                Something went wrong
              </h1>
            </div>
            <p className="text-gray-600 mb-4">
              We're sorry, but something unexpected happened. Please try
              refreshing the page.
            </p>
            {this.state.error && (
              <div className="bg-red-50 border border-red-200 rounded p-3 mb-4">
                <p className="text-sm text-red-800 font-mono">
                  {this.state.error.toString()}
                </p>
              </div>
            )}
            <button
              onClick={() => window.location.reload()}
              className="w-full bg-indigo-600 text-white py-2 px-4 rounded-lg hover:bg-indigo-700 transition-colors"
            >
              Refresh Page
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState } from "react";
import { Edit2, X, Save } from "lucide-react";
import { expenseAPI, APIError } from "../services/api";
import { useToast } from "../hooks/useToast";

const ExpenseEdit = ({ expense, onSuccess, onCancel, currentUser }) => {
  const { success, error: showError } = useToast();
  const [formData, setFormData] = useState({
    amount: expense.amount.toString(),
    category: expense.category,
    vendor: expense.vendor,
    description: expense.description,
  });
  const [saving, setSaving] = useState(false);

  // Get user_id from expense or current user
  const userId = expense.user_id || currentUser?.id;

  const handleSubmit = async () => {
    if (!formData.amount || !formData.vendor || !formData.description) {
      showError("Please fill in all required fields");
      return;
    }

    if (!userId) {
      showError("User ID is missing. Please try refreshing the page.");
      console.error(
        "Missing user_id - expense:",
        expense,
        "currentUser:",
        currentUser,
      );
      return;
    }

    setSaving(true);

    try {
      const updatedData = {
        user_id: userId, // Use the userId from expense or current user
        amount: parseFloat(formData.amount),
        category: formData.category,
        vendor: formData.vendor,
        description: formData.description,
      };

      console.log("Submitting update:", updatedData); // Debug log

      const result = await expenseAPI.updateExpense(expense.id, updatedData);
      const updatedExpense = result.expense || result;

      success("Expense updated successfully");
      onSuccess(updatedExpense);
    } catch (err) {
      console.error("Update error:", err); // Debug log
      console.error("Full error data:", err.data); // Log full error response

      const errorMsg =
        err instanceof APIError
          ? err.getUserMessage()
          : "Failed to update expense";
      showError(errorMsg);

      // Log validation errors if present
      if (err.validationErrors) {
        console.error("Validation errors:", err.validationErrors);
        // Log each validation error detail
        err.validationErrors.forEach((error, index) => {
          console.error(`Validation error ${index + 1}:`, error);
        });
      }
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg p-6 w-full max-w-md">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <Edit2 className="w-6 h-6 text-indigo-600" />
            Edit Expense
          </h2>
          <button onClick={onCancel} className="p-1 hover:bg-gray-100 rounded">
            <X className="w-6 h-6 text-gray-600" />
          </button>
