import React, { useState, useEffect } from "react";
import {
  Building2,
  Users,
  Settings,
  UserPlus,
  Mail,
  Edit,
  Trash2,
  Check,
  X,
  Plus,
  Search,
  RefreshCw,
  AlertCircle,
  Globe,
  Clock,
  Shield,
  Crown,
  ChevronDown,
  Copy,
  ArrowLeft,
} from "lucide-react";
import { useAuth } from "../contexts/AuthContext";
import { useToast } from "../hooks/useToast";
import { ToastContainer } from "./Toast";
import organizationAPI from "../services/organizationAPI";
import UpgradePrompt from "./upsell/UpgradePrompt";

const OrganizationManagement = () => {
  const { user } = useAuth();
  const { toasts, removeToast, success, error: showError } = useToast();

  const [activeTab, setActiveTab] = useState("overview");
  const [organizations, setOrganizations] = useState([]);
  const [currentOrg, setCurrentOrg] = useState(null);
  const [members, setMembers] = useState([]);
  const [invitations, setInvitations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);

  // Modals
  const [showCreateOrgModal, setShowCreateOrgModal] = useState(false);
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [showEditOrgModal, setShowEditOrgModal] = useState(false);
  const [showUpgradePrompt, setShowUpgradePrompt] = useState(false);
  const [upgradeTierInfo, setUpgradeTierInfo] = useState(null);
  const [showValidationError, setShowValidationError] = useState(false);
  const [validationErrorInfo, setValidationErrorInfo] = useState(null);

  // Forms
  const [createOrgForm, setCreateOrgForm] = useState({
    name: "",
    slug: "",
    description: "",
    currency: "USD",
    timezone: "UTC",
  });
  const [editOrgForm, setEditOrgForm] = useState({});
  const [inviteForm, setInviteForm] = useState({ email: "", role: "member" });
  const [bulkEmails, setBulkEmails] = useState("");
  const [showBulk, setShowBulk] = useState(false);

  // Real-time validation state
  const [nameValidation, setNameValidation] = useState({
    checking: false,
    result: null,
  });
  const [slugValidation, setSlugValidation] = useState({
    checking: false,
    result: null,
  });

  // Debounced name validation
  useEffect(() => {
    if (!createOrgForm.name || createOrgForm.name.trim().length === 0) {
      setNameValidation({ checking: false, result: null });
      return;
    }

    setNameValidation({ checking: true, result: null });

    const timer = setTimeout(async () => {
      try {
        const result = await organizationAPI.checkNameAvailability(
          createOrgForm.name,
        );
        setNameValidation({ checking: false, result });
      } catch (err) {
        console.error("Name validation error:", err);
        setNameValidation({ checking: false, result: null });
      }
    }, 500); // 500ms debounce

    return () => clearTimeout(timer);
  }, [createOrgForm.name]);

  // Debounced slug validation
  useEffect(() => {
    if (!createOrgForm.slug || createOrgForm.slug.trim().length === 0) {
      setSlugValidation({ checking: false, result: null });
      return;
    }

    setSlugValidation({ checking: true, result: null });

    const timer = setTimeout(async () => {
      try {
        const result = await organizationAPI.checkSlugAvailability(
          createOrgForm.slug,
        );
        setSlugValidation({ checking: false, result });
      } catch (err) {
        console.error("Slug validation error:", err);
        setSlugValidation({ checking: false, result: null });
      }
    }, 500); // 500ms debounce

    return () => clearTimeout(timer);
  }, [createOrgForm.slug]);

  useEffect(() => {
    fetchOrganizations();
  }, []);

  useEffect(() => {
    if (currentOrg) {
      // Save to localStorage and dispatch event for other components (like Billing)
      organizationAPI.setCurrentOrganizationId(currentOrg.id);
      window.dispatchEvent(
        new CustomEvent("organizationChanged", {
          detail: { orgId: currentOrg.id },
        }),
      );

      fetchOrgMembers();
      fetchOrgInvitations();
    }
  }, [currentOrg]);

  const fetchOrganizations = async () => {
    try {
      setLoading(true);
      const data = await organizationAPI.listOrganizations();
      setOrganizations(data);

      if (data.length > 0 && !currentOrg) {
        // Check if there's a saved organization in localStorage
        const savedOrgId = organizationAPI.getCurrentOrganizationId();
        const savedOrg = savedOrgId
          ? data.find((org) => org.id === savedOrgId)
          : null;

        // Use saved org if found, otherwise use first org
        setCurrentOrg(savedOrg || data[0]);
      }
    } catch (err) {
      showError("Failed to load organizations");
    } finally {
      setLoading(false);
    }
  };

  const fetchOrgMembers = async () => {
    if (!currentOrg) return;
    try {
      const data = await organizationAPI.listMembers(currentOrg.id);
      setMembers(data);
    } catch (err) {
      showError("Failed to load members");
    }
  };

  const fetchOrgInvitations = async () => {
    if (!currentOrg) return;
    try {
      const data = await organizationAPI.listInvitations(currentOrg.id);
      setInvitations(data);
    } catch (err) {
      console.error("Failed to load invitations:", err);
    }
  };

  const handleCreateOrg = async (e) => {
    e.preventDefault();
    setProcessing(true);
    try {
      const newOrg = await organizationAPI.createOrganization(createOrgForm);
      success(`Organization "${newOrg.name}" created!`);
      setOrganizations([...organizations, newOrg]);
      setCurrentOrg(newOrg);
      setShowCreateOrgModal(false);
      setCreateOrgForm({
        name: "",
        slug: "",
        description: "",
        currency: "USD",
        timezone: "UTC",
      });
    } catch (err) {
      // Handle Free tier limit (402 Payment Required)
      if (err.status === 402) {
        const errorData = err.data || {};

        //console.log("402 Error Data:", errorData); // Debug log
       // console.log("Message field:", errorData.message); // Debug message field

        // Extract just the message string, ensure it's not the entire object
       // const messageText = typeof errorData.message === 'string'
       //   ? errorData.message
       //   : "You have reached your organization limit.You've reached your plan's limit of 1 organization. Upgrade to Starter ($29/month) to create up to 3 organizations";

      const messageText =
      typeof errorData.message === "string"
       ? errorData.message
       : "You have reached your plan's organization limit. Upgrade to create more organizations.";

      console.log("Extracted message:", messageText); // Debug extracted message

        // Store tier info for upgrade prompt with new backend format
        setUpgradeTierInfo({
          currentTier: errorData.current_tier || "Free",
          currentLimit: errorData.current_limit || 1,
          currentCount: errorData.current_count || 1,
          message: messageText,
          upgradeOptions: errorData.upgrade_options || null,
        });

        // Close create modal
        setShowCreateOrgModal(false);

        // Show upgrade prompt modal
        setShowUpgradePrompt(true);
        return
      }
      // Handle Pydantic validation errors (422 Unprocessable Entity)
      else if (err.status === 422 && err.data?.detail) {
        const details = Array.isArray(err.data.detail) ? err.data.detail : [err.data.detail];
        const errorMessages = details.map(detail => {
          const field = detail.loc ? detail.loc[detail.loc.length - 1] : 'field';
          let msg = detail.msg || 'Validation error';

          // Make validation messages more user-friendly
          if (msg.includes('at least 3 characters')) {
            msg = `must be at least 3 characters long`;
          } else if (msg.includes('string does not match regex')) {
            msg = `can only contain lowercase letters, numbers, and hyphens`;
          }

          return `${field}: ${msg}`;
        }).join('\n');

        showError(`Validation Error:\n${errorMessages}`);
      }
      // Handle validation errors with suggestions (400 Bad Request)
      else if (err.status === 400 && err.data) {
        // Extract error data (wrapped in "detail" by backend)
        const errorData = err.data.detail || err.data;

        // Store validation error info for modal
        setValidationErrorInfo({
          error: errorData.error || "validation_error",
          message: errorData.message || err.message || "Validation failed",
          field: errorData.field || "unknown",
          suggestions: errorData.suggestions || [],
          hint: errorData.hint || null,
          requirement: errorData.requirement || null,
        });

        // Close create modal
        setShowCreateOrgModal(false);

        // Show validation error modal
        setShowValidationError(true);
        return;
      } else {
        // Fallback error handling - ensure we always show a string
        console.error("Organization creation error:", err);
        const errorMessage =
          typeof err === 'string' ? err :
          typeof err.message === 'string' ? err.message :
          err.data?.message || err.data?.detail ||
          "Failed to create organization. Please check your inputs and try again.";
        showError(errorMessage);
      }
    } finally {
      setProcessing(false);
    }
  };

  const handleUpdateOrg = async (e) => {
    e.preventDefault();
    if (!currentOrg) return;
    setProcessing(true);
    try {
      const updated = await organizationAPI.updateOrganization(
        currentOrg.id,
        editOrgForm,
      );
      success("Organization updated!");
      setOrganizations(
        organizations.map((o) => (o.id === updated.id ? updated : o)),
      );
      setCurrentOrg(updated);
      setShowEditOrgModal(false);
    } catch (err) {
      showError(err.message);
    } finally {
      setProcessing(false);
    }
  };

  const handleInvite = async (e) => {
    e.preventDefault();
    if (!currentOrg) return;
    setProcessing(true);
    try {
      await organizationAPI.createInvitation(
        currentOrg.id,
        inviteForm.email,
        inviteForm.role,
      );
      success(`Invitation sent to ${inviteForm.email}!`);
      setShowInviteModal(false);
      setInviteForm({ email: "", role: "member" });
      fetchOrgInvitations();
    } catch (err) {
      console.error("Invitation error:", err);

      // Handle Free tier limit (402 Payment Required)
      if (err.status === 402) {
        const errorData = err.data?.detail || err.data || {};

        const messageText =
          typeof errorData.message === "string"
            ? errorData.message
            : errorData.upgrade_message ||
              "You have reached your plan's team member limit. Upgrade to invite more members.";

        // Store tier info for upgrade prompt
        setUpgradeTierInfo({
          currentTier: errorData.current_tier || "Free",
          currentLimit: errorData.limit || 1,
          currentCount: errorData.current || 1,
          message: messageText,
          upgradeOptions: errorData.upgrade_options || { next_tier: "Starter" },
        });

        // Close invite modal
        setShowInviteModal(false);

        // Show upgrade prompt modal
        setShowUpgradePrompt(true);
        return;
      }

      // For other errors, show toast notification
      showError(err.message || "Failed to send invitation");
    } finally {
      setProcessing(false);
    }
  };

  const handleBulkInvite = async () => {
    if (!currentOrg || !bulkEmails.trim()) return;
    setProcessing(true);

    try {
      const emails = bulkEmails
        .split("\n")
        .map((e) => e.trim())
        .filter((e) => e);

      const results = await organizationAPI.bulkInviteMembers(
        currentOrg.id,
        emails,
        "member",
      );

      // Show success/failure summary
      if (results.failed.length > 0) {
        // Show first error message if all failed
        if (results.successful.length === 0) {
          showError(results.failed[0].error || "Failed to send invitations");
        } else {
          // Show mixed results
          success(
            `Sent: ${results.successful.length} successful, ${results.failed.length} failed`,
          );
        }
      } else {
        success(`Successfully invited ${results.successful.length} member(s)!`);
      }

      setBulkEmails("");
      setShowBulk(false);
      fetchOrgInvitations();
    } catch (err) {
      console.error("Bulk invite error:", err);

      // Handle Free tier limit (402 Payment Required)
      if (err.status === 402) {
        const errorData = err.data?.detail || err.data || {};

        const messageText =
          typeof errorData.message === "string"
            ? errorData.message
            : errorData.upgrade_message ||
              "You have reached your plan's team member limit. Upgrade to invite more members.";

        // Store tier info for upgrade prompt
        setUpgradeTierInfo({
          currentTier: errorData.current_tier || "Free",
          currentLimit: errorData.limit || 1,
          currentCount: errorData.current || 1,
          message: messageText,
          upgradeOptions: errorData.upgrade_options || { next_tier: "Starter" },
        });

        // Close bulk invite modal
        setShowBulk(false);

        // Show upgrade prompt modal
        setShowUpgradePrompt(true);
        return;
      }

      // For other errors, show toast notification
      showError(err.message || "Failed to send invitations");
    } finally {
      setProcessing(false);
    }
  };

  const handleUpdateRole = async (memberId, newRole) => {
    if (!currentOrg) return;
    setProcessing(true);
    try {
      await organizationAPI.updateMemberRole(currentOrg.id, memberId, newRole);
      success("Role updated!");
      fetchOrgMembers();
    } catch (err) {
      showError(err.message);
    } finally {
      setProcessing(false);
    }
  };

  const handleRemoveMember = async (memberId) => {
    if (!currentOrg || !confirm("Remove this member?")) return;
    setProcessing(true);
    try {
      await organizationAPI.removeMember(currentOrg.id, memberId);
      success("Member removed");
      fetchOrgMembers();
    } catch (err) {
      showError(err.message);
    } finally {
      setProcessing(false);
    }
  };

  const handleDeleteOrg = async () => {
    if (!currentOrg) return;

    // Use organization slug for confirmation to avoid apostrophe/quote issues
    const confirmText = currentOrg.slug.toLowerCase();

    const userInput = prompt(
      `⚠️ WARNING: This will permanently delete "${currentOrg.name}" and all associated data.\n\n` +
        `This action CANNOT be undone.\n\n` +
        `To confirm, type the organization ID: ${confirmText}`,
    );

    // Case-insensitive comparison and trim whitespace
    if (userInput?.toLowerCase().trim() !== confirmText) {
      if (userInput !== null) {
        showError("Deletion cancelled - confirmation text did not match");
      }
      return;
    }

    setProcessing(true);
    const orgName = currentOrg.name; // Store name before deletion
    const deletedOrgId = currentOrg.id; // Store ID before deletion
    try {
      await organizationAPI.deleteOrganization(currentOrg.id);

      // Clear current org immediately
      setCurrentOrg(null);

      // Refetch organizations to ensure we get updated list from server
      const data = await organizationAPI.listOrganizations();
      setOrganizations(data);

      // Select first available organization or null if none left
      if (data.length > 0) {
        // Select a different org (not the deleted one)
        const nextOrg = data.find((org) => org.id !== deletedOrgId) || data[0];
        setCurrentOrg(nextOrg);
      } else {
        setCurrentOrg(null);
      }

      // Show success confirmation
      success(`✓ Organization "${orgName}" has been permanently deleted`);

      // Additional confirmation alert
      setTimeout(() => {
        alert(
          `✓ Deletion Confirmed\n\nOrganization "${orgName}" and all associated data have been permanently removed.`,
        );
      }, 500);
    } catch (err) {
      showError(err.message);
    } finally {
      setProcessing(false);
    }
  };

  const handleRevokeInvite = async (inviteId) => {
    if (!currentOrg) return;
    setProcessing(true);
    try {
      await organizationAPI.revokeInvitation(currentOrg.id, inviteId);
      success("Invitation revoked");
      fetchOrgInvitations();
    } catch (err) {
      showError(err.message);
    } finally {
      setProcessing(false);
    }
  };

  const getRoleColor = (role) => {
    const colors = {
      owner: "bg-purple-100 text-purple-800",
      admin: "bg-blue-100 text-blue-800",
      manager: "bg-green-100 text-green-800",
      member: "bg-gray-100 text-gray-800",
    };
    return colors[role] || colors.member;
  };

  const getRoleIcon = (role) => {
    switch (role) {
      case "owner":
        return <Crown className="w-4 h-4" />;
      case "admin":
        return <Shield className="w-4 h-4" />;
      default:
        return null;
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-indigo-100 rounded-full mb-4">
            <RefreshCw className="w-8 h-8 animate-spin text-indigo-600" />
          </div>
          <p className="text-gray-600">Loading organizations...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Toast Notifications */}
      <ToastContainer toasts={toasts} onClose={removeToast} />

      {/* Header */}
      <div className="bg-white border-b">
        <div className="max-w-7xl mx-auto px-4 py-6">
          {/* Back to Dashboard Button */}
          {user?.role === "admin" && (
            <button
              onClick={() => (window.location.href = "/")}
              className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-4 transition-colors"
            >
              <ArrowLeft className="w-4 h-4" />
              Back to Dashboard
            </button>
          )}

          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
                <Building2 className="w-8 h-8 text-indigo-600" />
                Organization Management
              </h1>
              <p className="text-gray-600 mt-1">
                Manage organizations, members, and team settings
                {organizations.length > 0 && (
                  <span className="ml-2 text-indigo-600 font-medium">
                    • {organizations.length}{" "}
                    {organizations.length === 1
                      ? "organization"
                      : "organizations"}
                  </span>
                )}
              </p>
            </div>
            {/* Only show Create button in header if organizations exist */}
            {organizations.length > 0 && (
              <div className="relative">
                <button
                  onClick={() => setShowCreateOrgModal(true)}
                  className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
                >
                  <Plus className="w-5 h-5" />
                  Create Organization
                </button>
              </div>
            )}
          </div>

          {/* Org Selector */}
          {organizations.length > 0 && (
            <div className="mt-6">
              <select
                value={currentOrg?.id || ""}
                onChange={(e) => {
                  const newOrg = organizations.find(
                    (o) => o.id === e.target.value,
                  );
                  setCurrentOrg(newOrg);

                  // Save to localStorage and notify other components
                  if (newOrg) {
                    organizationAPI.setCurrentOrganizationId(newOrg.id);
                    window.dispatchEvent(
                      new CustomEvent("organizationChanged", {
                        detail: { organizationId: newOrg.id },
                      }),
                    );
                  }
                }}
                className="block w-full max-w-md pl-4 pr-10 py-3 border-gray-300 rounded-lg"
              >
                {organizations.map((org) => (
                  <option key={org.id} value={org.id}>
                    {org.name}
                  </option>
