import React, { useEffect } from "react";
import { CheckCircle, XCircle, AlertCircle, Info, X } from "lucide-react";

const Toast = ({ toast, onClose }) => {
  const icons = {
    success: <CheckCircle className="w-5 h-5 text-green-500" />,
    error: <XCircle className="w-5 h-5 text-red-500" />,
    warning: <AlertCircle className="w-5 h-5 text-yellow-500" />,
    info: <Info className="w-5 h-5 text-blue-500" />,
  };

  const bgColors = {
    success: "bg-green-50 border-green-200",
    error: "bg-red-50 border-red-200",
    warning: "bg-yellow-50 border-yellow-200",
    info: "bg-blue-50 border-blue-200",
  };

  const textColors = {
    success: "text-green-800",
    error: "text-red-800",
    warning: "text-yellow-800",
    info: "text-blue-800",
  };

  // Auto-dismiss functionality
  useEffect(() => {
    if (toast.duration && toast.duration > 0) {
      const timer = setTimeout(() => {
        onClose(toast.id);
      }, toast.duration);

      return () => clearTimeout(timer);
    }
  }, [toast.id, toast.duration, onClose]);

  return (
    <div
      role="status"
      aria-live={toast.type === "error" ? "assertive" : "polite"}
      data-testid={`toast-${toast.type}`}
      className={`flex items-center gap-3 p-4 rounded-lg border ${bgColors[toast.type]} shadow-lg min-w-[300px] max-w-md animate-slide-in`}
    >
      {icons[toast.type]}
      <p
        data-testid="toast-message"
        className={`flex-1 text-sm font-medium ${textColors[toast.type]}`}
      >
        {toast.message}
      </p>
      <button
        onClick={() => onClose(toast.id)}
        aria-label="Close notification"
        className="text-gray-400 hover:text-gray-600 transition-colors"
      >
        <X className="w-4 h-4" aria-hidden="true" />
      </button>
    </div>
  );
};

export const ToastContainer = ({ toasts, onClose }) => {
  if (toasts.length === 0) return null;

  return (
    <div className="fixed top-4 right-4 z-[60] flex flex-col gap-2">
      {toasts.map((toast) => (
        <Toast key={toast.id} toast={toast} onClose={onClose} />
      ))}
    </div>
  );
};

export default Toast;

/**
 * Toast Component Tests
 *
 * Tests the Toast notification component for:
 * - Rendering different toast types
 * - Accessibility (aria-live, role)
 * - Auto-dismiss functionality
 * - Close button interaction
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import Toast from './Toast';

describe('Toast Component', () => {
  const mockOnClose = vi.fn();

  const defaultToast = {
    id: 'test-toast-1',
    type: 'success',
    message: 'Operation successful',
  };

  beforeEach(() => {
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  describe('Rendering', () => {
    it('should render success toast with correct message', () => {
      render(<Toast toast={defaultToast} onClose={mockOnClose} />);

      expect(screen.getByText('Operation successful')).toBeInTheDocument();
    });

    it('should render error toast with error styling', () => {
      const errorToast = { ...defaultToast, type: 'error', message: 'Error occurred' };
      render(<Toast toast={errorToast} onClose={mockOnClose} />);

      expect(screen.getByText('Error occurred')).toBeInTheDocument();
      expect(screen.getByRole('status')).toBeInTheDocument();
    });

    it('should render info toast', () => {
      const infoToast = { ...defaultToast, type: 'info', message: 'Information message' };
      render(<Toast toast={infoToast} onClose={mockOnClose} />);

      expect(screen.getByText('Information message')).toBeInTheDocument();
    });

    it('should render warning toast', () => {
      const warningToast = { ...defaultToast, type: 'warning', message: 'Warning message' };
      render(<Toast toast={warningToast} onClose={mockOnClose} />);

      expect(screen.getByText('Warning message')).toBeInTheDocument();
    });
  });

  describe('Accessibility', () => {
    it('should have role="status" for screen readers', () => {
      render(<Toast toast={defaultToast} onClose={mockOnClose} />);

      const toast = screen.getByRole('status');
      expect(toast).toBeInTheDocument();
    });

    it('should have aria-live="polite" for non-error toasts', () => {
      render(<Toast toast={defaultToast} onClose={mockOnClose} />);

      const toast = screen.getByRole('status');
      expect(toast).toHaveAttribute('aria-live', 'polite');
    });

    it('should have aria-live="assertive" for error toasts', () => {
      const errorToast = { ...defaultToast, type: 'error' };
      render(<Toast toast={errorToast} onClose={mockOnClose} />);

      const toast = screen.getByRole('status');
      expect(toast).toHaveAttribute('aria-live', 'assertive');
    });

    it('should have accessible close button', () => {
      render(<Toast toast={defaultToast} onClose={mockOnClose} />);

      const closeButton = screen.getByRole('button', { name: /close/i });
      expect(closeButton).toBeInTheDocument();
    });
  });

  describe('Interaction', () => {
    it('should call onClose when close button is clicked', async () => {
      const user = userEvent.setup({ delay: null });
      render(<Toast toast={defaultToast} onClose={mockOnClose} />);

      const closeButton = screen.getByRole('button');
      await user.click(closeButton);

      expect(mockOnClose).toHaveBeenCalledWith(defaultToast.id);
      expect(mockOnClose).toHaveBeenCalledTimes(1);
    });

    it('should auto-dismiss after timeout', () => {
      vi.useFakeTimers();
      const autoCloseToast = { ...defaultToast, duration: 3000 };
      render(<Toast toast={autoCloseToast} onClose={mockOnClose} />);

      // Fast-forward time
      vi.advanceTimersByTime(3000);

      // Check that onClose was called
      expect(mockOnClose).toHaveBeenCalledWith(defaultToast.id);
      vi.useRealTimers();
    });

    it('should not auto-dismiss if duration is 0', () => {
      vi.useFakeTimers();
      const persistentToast = { ...defaultToast, duration: 0 };
      render(<Toast toast={persistentToast} onClose={mockOnClose} />);

      vi.advanceTimersByTime(10000);

      expect(mockOnClose).not.toHaveBeenCalled();
      vi.useRealTimers();
    });
  });

  describe('Icons', () => {
    it('should display success icon for success type', () => {
      render(<Toast toast={defaultToast} onClose={mockOnClose} />);

      // Check for success icon (CheckCircle)
      const container = screen.getByRole('status');
      expect(container.querySelector('svg')).toBeInTheDocument();
    });

    it('should display error icon for error type', () => {
      const errorToast = { ...defaultToast, type: 'error' };
      render(<Toast toast={errorToast} onClose={mockOnClose} />);

      const container = screen.getByRole('status');
      expect(container.querySelector('svg')).toBeInTheDocument();
    });
  });
});

import React, { useState, useEffect } from "react";
import {
  Users,
  UserPlus,
  Edit,
  Trash2,
  Shield,
  Lock,
  Unlock,
  Search,
  Filter,
  Eye,
  Check,
  X,
  AlertCircle,
  EyeOff,
  UserCheck,
  UserX,
} from "lucide-react";
import { useToast } from "../hooks/useToast";
import { useAuth } from "../contexts/AuthContext";
import adminAPI from "../services/adminAPI";
import { API_BASE_URL } from "../config/constants";
import { extractUserData, extractErrorMessage } from "../services/apiHelpers";

const UserManagementDashboard = () => {
  const { user: currentUser, getAuthHeaders, fetchWithAuth } = useAuth();
  const { success, error: showError } = useToast();

  const [users, setUsers] = useState([]);
  const [allUsers, setAllUsers] = useState([]); // Store all users for accurate stats
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [roleFilter, setRoleFilter] = useState("all");
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showPermissionsModal, setShowPermissionsModal] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [userPermissions, setUserPermissions] = useState([]);
  const [processing, setProcessing] = useState(false);
  const [showCreatePassword, setShowCreatePassword] = useState(false);
  const [organizations, setOrganizations] = useState([]);

  // Form states
  const [createForm, setCreateForm] = useState({
    email: "",
    username: "",
    full_name: "",
    password: "",
    role: "EMPLOYEE",
    department_id: "",
  });

  const [editForm, setEditForm] = useState({
    username: "",
    full_name: "",
    email: "",
    role: "",
    department_id: "",
    organization_id: "",
    is_active: true,
  });

  // Fetch all users for stats on initial load
  useEffect(() => {
    fetchAllUsersForStats();
    fetchOrganizations();
  }, []);

  // Debounce search to avoid too many API calls while typing
  useEffect(() => {
    const timer = setTimeout(() => {
      fetchUsers();
    }, 300); // 300ms delay

    return () => clearTimeout(timer);
  }, [searchTerm, roleFilter]);

  // Auto-refresh every 30 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      fetchAllUsersForStats();
      fetchUsers();
    }, 30000);
    return () => clearInterval(interval);
  }, [searchTerm, roleFilter]);

  const fetchAllUsersForStats = async () => {
    try {
      const data = await adminAPI.listUsers(1, 1000, null, null);
      setAllUsers(data.users || []);
    } catch (err) {
      console.error("Error fetching all users for stats:", err);
    }
  };

  const fetchOrganizations = async () => {
    try {
      const response = await fetchWithAuth(`${API_BASE_URL}/api/v1/admin/organizations`);
      if (response.ok) {
        const data = await response.json();
        setOrganizations(data.organizations || []);
      }
    } catch (err) {
      console.error("Error fetching organizations:", err);
    }
  };

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const data = await adminAPI.listUsers(
        1, // page
        100, // per page
        searchTerm || null,
        roleFilter !== "all" ? roleFilter.toLowerCase() : null,
      );
      setUsers(data.users || []);
    } catch (err) {
      console.error("Error fetching users:", err);
      showError("Failed to load users");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateUser = async (e) => {
    e.preventDefault();

    // Validate organization exists
    const orgId = localStorage.getItem("current_organization_id");
    if (!orgId) {
      showError(
        "No organization found. Please log out and log back in, or contact support if the issue persists."
      );
      return;
    }

    setProcessing(true);

    try {
      const data = await adminAPI.createUser({
        ...createForm,
        role: createForm.role.toLowerCase(),
        department_id: createForm.department_id || null,
      });

      // Use helper to safely extract user data (handles both nested and flat structures)
      const userData = extractUserData(data);
      success(`User ${userData.username} created successfully!`);

      setShowCreateModal(false);
      setCreateForm({
        email: "",
        username: "",
        full_name: "",
        password: "",
        role: "EMPLOYEE",
        department_id: "",
      });
      fetchUsers();
    } catch (err) {
      // Use helper to extract user-friendly error message
      showError(extractErrorMessage(err));
    } finally {
      setProcessing(false);
    }
  };

  const handleEditUser = async (e) => {
    e.preventDefault();
    if (!selectedUser) return;

    setProcessing(true);

    try {
      // Check if profile fields changed (username, full_name, email)
      const profileChanged =
        editForm.username !== selectedUser.username ||
        editForm.full_name !== selectedUser.full_name ||
        editForm.email !== selectedUser.email;

      // Update profile (username, full_name, email) using new consolidated endpoint
      if (profileChanged) {
        const profileData = {};
        if (editForm.username !== selectedUser.username) {
          profileData.username = editForm.username;
        }
        if (editForm.full_name !== selectedUser.full_name) {
          profileData.full_name = editForm.full_name;
        }
        if (editForm.email !== selectedUser.email) {
          profileData.email = editForm.email;
        }

        const profileResponse = await fetchWithAuth(
          `${API_BASE_URL}/api/v1/admin/users/${selectedUser.id}/profile`,
          {
            method: "PATCH",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify(profileData),
          },
        );

        if (!profileResponse.ok) {
          const errorData = await profileResponse.json().catch(() => ({}));
          const errorMessage =
            errorData.detail ||
            errorData.message ||
            `Failed to update profile (${profileResponse.status})`;
          throw new Error(errorMessage);
        }
      }

      // Update role (convert to lowercase for backend)
      const roleResponse = await fetchWithAuth(
        `${API_BASE_URL}/api/v1/admin/users/${selectedUser.id}/role`,
        {
          method: "PATCH",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ role: editForm.role.toLowerCase() }),
        },
      );

      if (!roleResponse.ok) {
        const errorData = await roleResponse.json().catch(() => ({}));
        const errorMessage =
          errorData.detail ||
          errorData.message ||
          `Failed to update role (${roleResponse.status})`;
        throw new Error(errorMessage);
      }

      // Update department
      const deptResponse = await fetchWithAuth(
        `${API_BASE_URL}/api/v1/admin/users/${selectedUser.id}/department`,
        {
          method: "PATCH",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            department_id: editForm.department_id || null,
          }),
        },
      );

      if (!deptResponse.ok) {
        throw new Error("Failed to update department");
      }

      // Update organization if changed
      const currentOrgId = selectedUser.organizations && selectedUser.organizations.length > 0
        ? selectedUser.organizations[0].id
        : "";
      if (editForm.organization_id && editForm.organization_id !== currentOrgId) {
        const orgResponse = await fetchWithAuth(
          `${API_BASE_URL}/api/v1/admin/users/${selectedUser.id}/organization`,
          {
            method: "PATCH",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              organization_id: editForm.organization_id,
            }),
          },
        );

        if (!orgResponse.ok) {
          throw new Error("Failed to update organization");
        }
      }

      // Update active status if changed
      if (editForm.is_active !== selectedUser.is_active) {
        const endpoint = editForm.is_active ? "activate" : "suspend";
        const action = editForm.is_active ? "activated" : "suspended";

        const statusResponse = await fetchWithAuth(
          `${API_BASE_URL}/api/v1/admin/users/${selectedUser.id}/${endpoint}`,
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body:
              endpoint === "suspend"
                ? JSON.stringify({ reason: "Admin action" })
                : undefined,
          },
        );

        if (!statusResponse.ok) {
          throw new Error(`Failed to ${endpoint} user`);
        }

        // Show specific success message for status change
        success(
          `User ${editForm.username} has been ${action}. ${endpoint === "suspend" ? "They will be logged out immediately and cannot log in until reactivated." : "They can now log in and access the system."}`,
        );
      } else {
        // Show generic success for other updates
        success(`User ${editForm.username} updated successfully!`);
      }

      setShowEditModal(false);
      setSelectedUser(null);
      fetchUsers();
    } catch (err) {
      // Show more descriptive error message
      const errorMessage = err.message || "Failed to update user";
      showError(
        `Error updating user: ${errorMessage}. Please try again or contact support if the issue persists.`,
      );
      console.error("Error updating user:", err);
    } finally {
      setProcessing(false);
    }
  };

  const handleDeleteUser = async () => {
    if (!selectedUser) return;

    setProcessing(true);

    try {
      const response = await fetchWithAuth(
        `${API_BASE_URL}/api/v1/admin/users/${selectedUser.id}`,
        {
          method: "DELETE",
        },
      );

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.detail || "Failed to delete user");
      }

      success(`User ${selectedUser.username} deleted successfully!`);
      setShowDeleteModal(false);
      setSelectedUser(null);
      fetchUsers();
