import React, { createContext, useState, useContext, useEffect } from "react";

const AuthContext = createContext(null);

// Export AuthContext for testing
export { AuthContext };

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const normalizeUserRole = (user) => {
    if (!user) return null;
    return {
      ...user,
      role: typeof user.role === "string" ? user.role.toLowerCase() : user.role,
    };
  };

  const [user, setUser] = useState(null);
  const [accessToken, setAccessToken] = useState(null);
  const [refreshToken, setRefreshToken] = useState(null);
  const [loading, setLoading] = useState(true);

  // Check for existing session on mount
  useEffect(() => {
    const storedAccessToken = localStorage.getItem("access_token");
    const storedRefreshToken = localStorage.getItem("refresh_token");
    const storedUser = localStorage.getItem("user");

    if (storedAccessToken && storedUser) {
      setAccessToken(storedAccessToken);
      setRefreshToken(storedRefreshToken);
      const parsedUser = JSON.parse(storedUser);
      setUser(normalizeUserRole(parsedUser));
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    if (!accessToken) return;

    const validateOrganization = async () => {
      try {
        const orgResponse = await fetch("/api/v1/organizations", {
          headers: {
            Authorization: `Bearer ${accessToken}`,
            "Content-Type": "application/json",
          },
        });
        if (!orgResponse.ok) return;

        const orgs = await orgResponse.json();
        const orgList = Array.isArray(orgs) ? orgs : orgs ? [orgs] : [];
        const savedOrgId = localStorage.getItem("current_organization_id");

        if (orgList.length === 0) {
          localStorage.removeItem("current_organization_id");
          return;
        }

        if (!savedOrgId || !orgList.some((org) => org.id === savedOrgId)) {
          localStorage.setItem("current_organization_id", orgList[0].id);
        }
      } catch (orgError) {
        console.warn("Failed to validate organizations:", orgError);
      }
    };

    validateOrganization();
  }, [accessToken]);

  const login = async (username, password, totpCode = null) => {
    try {
      const response = await fetch("/api/v1/auth/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ username, password, totp_code: totpCode }),
      });

      if (!response.ok) {
        let errorMessage = "Login failed";

        // Try to get error message from response
        try {
          const error = await response.json();
          if (error.detail) {
            errorMessage = error.detail;
          }
        } catch (jsonError) {
          // If we can't parse JSON, provide status-based message
          console.error("Failed to parse error response:", jsonError);
        }

        // If we still don't have a specific message, use status-based fallbacks
        if (errorMessage === "Login failed") {
          if (response.status === 401) {
            errorMessage = "Invalid username or password";
          } else if (response.status === 423) {
            errorMessage = "Account locked. Please try again later.";
          } else if (response.status === 403) {
            errorMessage = "Account suspended. Contact your administrator.";
          } else if (!response.status) {
            errorMessage = "Cannot connect to server. Please check your connection.";
          } else {
            errorMessage = "Login failed. Please try again.";
          }
        }

        throw new Error(errorMessage);
      }

      let data;
      try {
        data = await response.json();
      } catch (jsonError) {
        throw new Error("Server error. Please try again later.");
      }

      setAccessToken(data.access_token);
      setRefreshToken(data.refresh_token);
      const normalizedUser = normalizeUserRole(data.user);
      setUser(normalizedUser);

      localStorage.setItem("access_token", data.access_token);
      localStorage.setItem("refresh_token", data.refresh_token);
      localStorage.setItem("user", JSON.stringify(normalizedUser));

      const savedOrgId = localStorage.getItem("current_organization_id");
      try {
        const orgResponse = await fetch("/api/v1/organizations", {
          headers: {
            Authorization: `Bearer ${data.access_token}`,
            "Content-Type": "application/json",
          },
        });
        if (orgResponse.ok) {
          const orgs = await orgResponse.json();
          const orgList = Array.isArray(orgs) ? orgs : orgs ? [orgs] : [];
          if (orgList.length === 0) {
            localStorage.removeItem("current_organization_id");
          } else if (!savedOrgId) {
            localStorage.setItem("current_organization_id", orgList[0].id);
          } else if (!orgList.some((org) => org.id === savedOrgId)) {
            localStorage.setItem("current_organization_id", orgList[0].id);
          }
        }
      } catch (orgError) {
        console.warn("Failed to fetch organizations after login:", orgError);
      }

      return { success: true };
    } catch (error) {
      return { success: false, error: error.message };
    }
  };

  const register = async (userData) => {
    try {
      const response = await fetch("/api/v1/auth/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(userData),
      });

      if (!response.ok) {
        const error = await response.json();
        // Handle both error formats: standard HTTPException (error.detail) and custom API errors (error.error.message)
        const errorMessage = error.detail || error.error?.message || "Registration failed";
        throw new Error(errorMessage);
      }

      const data = await response.json();
      return { success: true, user: data };
    } catch (error) {
      return { success: false, error: error.message };
    }
  };

  const logout = async () => {
    try {
      if (refreshToken) {
        await fetch("/api/v1/auth/logout", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${accessToken}`,
          },
          body: JSON.stringify({ refresh_token: refreshToken }),
        });
      }
    } catch (error) {
      console.error("Logout error:", error);
    } finally {
      setAccessToken(null);
      setRefreshToken(null);
      setUser(null);
      localStorage.removeItem("access_token");
      localStorage.removeItem("refresh_token");
      localStorage.removeItem("user");
      localStorage.removeItem("current_organization_id");
    }
  };

  const refreshAccessToken = async () => {
    try {
      const response = await fetch("/api/v1/auth/refresh", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ refresh_token: refreshToken }),
      });

      if (!response.ok) {
        throw new Error("Token refresh failed");
      }

      const data = await response.json();
      setAccessToken(data.access_token);
      localStorage.setItem("access_token", data.access_token);

      return data.access_token;
    } catch (error) {
      logout();
      throw error;
    }
  };

  const apiRequest = async (url, options = {}) => {
    const headers = {
      ...options.headers,
      "Content-Type": "application/json",
      Authorization: `Bearer ${accessToken}`,
    };

    let response = await fetch(url, { ...options, headers });

    // If token expired, try to refresh
    if (response.status === 401 && refreshToken) {
      try {
        const newAccessToken = await refreshAccessToken();
        headers["Authorization"] = `Bearer ${newAccessToken}`;
        response = await fetch(url, { ...options, headers });
      } catch (error) {
        logout();
        throw error;
      }
    }

    // If account is suspended/inactive, logout and notify user
    if (response.status === 403) {
      try {
        const errorData = await response.clone().json();
        if (errorData.detail === "User account is inactive") {
          logout();
          throw new Error(
            "Your account has been suspended. Please contact your administrator.",
          );
        }
      } catch (error) {
        // If it's already our custom error, re-throw it
        if (
          error.message ===
          "Your account has been suspended. Please contact your administrator."
        ) {
          throw error;
        }
        // Otherwise, it's a different 403 error, let it pass through
      }
    }

    return response;
  };

  const getAuthHeaders = () => {
    return {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
    };
  };

  // Enhanced fetch with automatic token refresh
  const fetchWithAuth = async (url, options = {}) => {
    const headers = {
      ...options.headers,
      Authorization: `Bearer ${accessToken}`,
    };

    let response = await fetch(url, { ...options, headers });

    // If token expired, try to refresh and retry
    if (response.status === 401 && refreshToken) {
      try {
        const newAccessToken = await refreshAccessToken();
        headers["Authorization"] = `Bearer ${newAccessToken}`;
        response = await fetch(url, { ...options, headers });
      } catch (error) {
        // Token refresh failed, logout user
        logout();
        throw new Error("Session expired. Please login again.");
      }
    }

    // If account is suspended/inactive, logout and notify user
    if (response.status === 403) {
      try {
        const errorData = await response.clone().json();
        if (errorData.detail === "User account is inactive") {
          logout();
          throw new Error(
            "Your account has been suspended. Please contact your administrator.",
          );
        }
      } catch (error) {
        // If it's already our custom error, re-throw it
        if (
          error.message ===
          "Your account has been suspended. Please contact your administrator."
        ) {
          throw error;
        }
        // Otherwise, it's a different 403 error, let it pass through
      }
    }

    return response;
  };

  const value = {
    user,
    accessToken,
    refreshToken,
    loading,
    isAuthenticated: !!accessToken,
    login,
    register,
    logout,
    refreshAccessToken,
    apiRequest,
    getAuthHeaders,
    fetchWithAuth,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

import React, { createContext, useState, useContext, useEffect, useCallback } from "react";
import organizationAPI from "../services/organizationAPI";

const OrganizationContext = createContext(null);

export const useOrganization = () => {
  const context = useContext(OrganizationContext);
  if (!context) {
    throw new Error(
      "useOrganization must be used within an OrganizationProvider",
    );
  }
  return context;
};

export const OrganizationProvider = ({ children }) => {
  const [organizations, setOrganizations] = useState([]);
  const [currentOrganization, setCurrentOrganization] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Load organizations on mount
  useEffect(() => {
    loadOrganizations();
  }, []);

  const loadOrganizations = async () => {
    try {
      setLoading(true);
      setError(null);

      const orgs = await organizationAPI.listOrganizations();
      setOrganizations(orgs);

      // Set current organization from localStorage or first org
      const savedOrgId = organizationAPI.getCurrentOrganizationId();
      if (savedOrgId) {
        const savedOrg = orgs.find((o) => o.id === savedOrgId);
        if (savedOrg) {
          setCurrentOrganization(savedOrg);
        } else if (orgs.length > 0) {
          setCurrentOrganization(orgs[0]);
          organizationAPI.setCurrentOrganizationId(orgs[0].id);
        }
      } else if (orgs.length > 0) {
        setCurrentOrganization(orgs[0]);
        organizationAPI.setCurrentOrganizationId(orgs[0].id);
      }
    } catch (err) {
      console.error("Failed to load organizations:", err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const switchOrganization = (orgId) => {
    const org = organizations.find((o) => o.id === orgId);
    if (org) {
      setCurrentOrganization(org);
      organizationAPI.setCurrentOrganizationId(org.id);
      return true;
    }
    return false;
  };

  const addOrganization = (org) => {
    setOrganizations((prev) => [...prev, org]);
    setCurrentOrganization(org);
    organizationAPI.setCurrentOrganizationId(org.id);
  };

  const updateOrganizationInList = (orgId, updates) => {
    setOrganizations((prev) =>
      prev.map((org) => (org.id === orgId ? { ...org, ...updates } : org)),
    );
    if (currentOrganization?.id === orgId) {
      setCurrentOrganization((prev) => ({ ...prev, ...updates }));
    }
  };

  const removeOrganization = (orgId) => {
    setOrganizations((prev) => prev.filter((org) => org.id !== orgId));
    if (currentOrganization?.id === orgId) {
      const remaining = organizations.filter((org) => org.id !== orgId);
      if (remaining.length > 0) {
        setCurrentOrganization(remaining[0]);
        organizationAPI.setCurrentOrganizationId(remaining[0].id);
      } else {
        setCurrentOrganization(null);
        organizationAPI.setCurrentOrganizationId(null);
      }
    }
  };

  const refetchOrganizations = async () => {
    await loadOrganizations();
  };

  // Get current organization's timezone (default to UTC)
  const timezone = currentOrganization?.timezone || "UTC";
  const currency = currentOrganization?.currency || "USD";

  // Format a date using the organization's timezone
  const formatDate = useCallback((dateString, options = {}) => {
    if (!dateString) return "";

    // Backend sends UTC time without 'Z', so append it if missing
    const dateStr = dateString.endsWith("Z") ? dateString : dateString + "Z";
    const date = new Date(dateStr);

    if (isNaN(date.getTime())) {
      return dateString;
    }

    const defaultOptions = {
      month: "short",
      day: "numeric",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      timeZone: timezone,
      ...options,
    };

    try {
      return date.toLocaleString("en-US", defaultOptions);
    } catch (error) {
      // Fallback to UTC if timezone is invalid
      return date.toLocaleString("en-US", { ...defaultOptions, timeZone: "UTC" });
    }
  }, [timezone]);

  // Format date without time
  const formatDateOnly = useCallback((dateString) => {
    return formatDate(dateString, {
      hour: undefined,
      minute: undefined,
    });
  }, [formatDate]);

  // Format with timezone abbreviation
  const formatDateFull = useCallback((dateString) => {
    return formatDate(dateString, {
      weekday: "short",
      timeZoneName: "short",
    });
  }, [formatDate]);

  const value = {
    organizations,
    currentOrganization,
    loading,
    error,
    switchOrganization,
    addOrganization,
    updateOrganizationInList,
    removeOrganization,
    refetchOrganizations,
    // Timezone helpers
    timezone,
    currency,
    formatDate,
    formatDateOnly,
    formatDateFull,
  };

  return (
    <OrganizationContext.Provider value={value}>
      {children}
    </OrganizationContext.Provider>
  );
};

import React, { createContext, useCallback, useContext, useMemo, useState } from "react";

const ToastContext = createContext(null);
let toastCounter = 0;

export const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = useState([]);

  const removeToast = useCallback((id) => {
    setToasts((prev) => prev.filter((toast) => toast.id !== id));
  }, []);

  const showToast = useCallback((message, type = "info") => {
    const id =
      typeof crypto !== "undefined" && crypto.randomUUID
        ? crypto.randomUUID()
        : `${Date.now()}-${toastCounter++}`;
    const toast = { id, message, type };

    setToasts((prev) => [...prev, toast]);

    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 5000);
  }, []);

  const value = useMemo(
    () => ({
      toasts,
      showToast,
      removeToast,
      success: (message) => showToast(message, "success"),
      error: (message) => showToast(message, "error"),
      info: (message) => showToast(message, "info"),
      warning: (message) => showToast(message, "warning"),
    }),
    [toasts, showToast, removeToast],
  );

  return (
    <ToastContext.Provider value={value}>{children}</ToastContext.Provider>
  );
};

export const useToast = () => {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error("useToast must be used within a ToastProvider");
  }
  return context;
};

/**
 * useTableKeyboardNav Hook
 *
 * Provides keyboard navigation for HTML tables
 *
 * Features:
 * - Arrow Up/Down: Navigate between rows
 * - Enter/Space: Activate selected row
 * - Home/End: Jump to first/last row
 * - ARIA attributes for accessibility
 *
 * Usage:
 * ```jsx
 * const { getRowProps, selectedIndex } = useTableKeyboardNav({
 *   rowCount: expenses.length,
 *   onRowActivate: (index) => handleExpenseClick(expenses[index])
 * });
 *
 * {expenses.map((expense, index) => (
 *   <tr {...getRowProps(index)}>
 *     ...
 *   </tr>
 * ))}
 * ```
 */

import { useState, useCallback } from 'react';

export const useTableKeyboardNav = ({
  rowCount = 0,
  onRowActivate = () => {},
  initialIndex = -1,
  enableArrowKeys = true,
  enableHomeEnd = true,
  enableEnterSpace = true,
}) => {
  const [selectedIndex, setSelectedIndex] = useState(initialIndex);

  const handleKeyDown = useCallback(
    (index, event) => {
      const { key } = event;

      // Arrow navigation
      if (enableArrowKeys) {
        if (key === 'ArrowDown') {
          event.preventDefault();
          const nextIndex = Math.min(index + 1, rowCount - 1);
          setSelectedIndex(nextIndex);
          // Focus next row
          const nextRow = event.currentTarget.parentElement.children[nextIndex + 1]; // +1 for header
          if (nextRow) nextRow.focus();
        } else if (key === 'ArrowUp') {
          event.preventDefault();
          const prevIndex = Math.max(index - 1, 0);
          setSelectedIndex(prevIndex);
          // Focus previous row
          const prevRow = event.currentTarget.parentElement.children[prevIndex + 1]; // +1 for header
          if (prevRow) prevRow.focus();
        }
      }

      // Home/End navigation
      if (enableHomeEnd) {
        if (key === 'Home') {
          event.preventDefault();
          setSelectedIndex(0);
          const firstRow = event.currentTarget.parentElement.children[1]; // After header
          if (firstRow) firstRow.focus();
        } else if (key === 'End') {
          event.preventDefault();
          setSelectedIndex(rowCount - 1);
          const lastRow = event.currentTarget.parentElement.children[rowCount]; // Header + rows
          if (lastRow) lastRow.focus();
        }
      }

      // Enter/Space activation
      if (enableEnterSpace) {
        if (key === 'Enter' || key === ' ') {
          event.preventDefault();
          setSelectedIndex(index);
          onRowActivate(index);
        }
      }
    },
    [rowCount, onRowActivate, enableArrowKeys, enableHomeEnd, enableEnterSpace]
  );

  const getRowProps = useCallback(
    (index, ariaLabel = '') => ({
      tabIndex: index === 0 ? 0 : -1, // Only first row in tab order
      role: 'row',
      'aria-rowindex': index + 2, // +2 for 1-based and header row
      'aria-label': ariaLabel,
      'aria-selected': selectedIndex === index,
      onKeyDown: (e) => handleKeyDown(index, e),
      onFocus: () => setSelectedIndex(index),
      className: selectedIndex === index ? 'bg-blue-50' : '',
      style: {
        cursor: 'pointer',
      },
    }),
    [selectedIndex, handleKeyDown]
  );

  return {
    selectedIndex,
    setSelectedIndex,
    getRowProps,
  };
};

export default useTableKeyboardNav;

