  );
};

// Activity Item Component
const ActivityItem = ({ mandate }) => {
  const getStatusIcon = (status) => {
    switch (status) {
      case "completed":
        return <CheckCircle className="w-5 h-5 text-green-500" />;
      case "active":
      case "pending":
        return <Clock className="w-5 h-5 text-yellow-500" />;
      case "failed":
        return <XCircle className="w-5 h-5 text-red-500" />;
      case "expired":
        return <Clock className="w-5 h-5 text-gray-400" />;
      case "revoked":
        return <XCircle className="w-5 h-5 text-orange-500" />;
      default:
        return <AlertTriangle className="w-5 h-5 text-gray-500" />;
    }
  };

  const getMandateTypeLabel = (type) => {
    switch (type) {
      case "intent":
        return "Reusable Authorization";
      case "cart":
        return "Cart Authorization";
      case "payment":
        return "Payment";
      default:
        return type;
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    const dateStr = dateString.endsWith('Z') ? dateString : dateString + 'Z';
    return new Date(dateStr).toLocaleString("en-US", {
      month: "short",
      day: "numeric",
      hour: "numeric",
      minute: "2-digit",
    });
  };

  const statusBadgeClass = {
    completed: "bg-green-100 text-green-800",
    active: "bg-yellow-100 text-yellow-800",
    pending: "bg-blue-100 text-blue-800",
    expired: "bg-gray-100 text-gray-800",
    revoked: "bg-orange-100 text-orange-800",
    failed: "bg-red-100 text-red-800",
    deleted: "bg-gray-100 text-gray-600",
  };

  return (
    <div className="px-6 py-4 hover:bg-gray-50 transition-colors">
      <div className="flex items-start space-x-4">
        <div className="flex-shrink-0 mt-1">
          {getStatusIcon(mandate.status)}
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium text-gray-900">
            {getMandateTypeLabel(mandate.type)}
            {mandate.total && (
              <span className="ml-2 text-gray-600">
                ${parseFloat(mandate.total).toFixed(2)}
              </span>
            )}
            {mandate.merchant && (
              <span className="ml-2 text-gray-500">
                @ {mandate.merchant}
              </span>
            )}
          </p>
          <p className="text-sm text-gray-500">
            {formatDate(mandate.created_at)}
          </p>
        </div>
        <div className="flex-shrink-0">
          <span
            className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
              statusBadgeClass[mandate.status] || "bg-gray-100 text-gray-800"
            }`}
          >
            {mandate.status}
          </span>
        </div>
      </div>
    </div>
  );
};

