                ["Total Estimated", `$${totalEstimated.toFixed(2)}`],
              ];

              const csvContent = reportData
                .map((row) => row.map(escapeCSV).join(","))
                .join("\n");
              const blob = new Blob([csvContent], {
                type: "text/csv;charset=utf-8;",
              });
              const url = URL.createObjectURL(blob);
