          >
            <Download className="w-4 h-4" />
            Export CSV
          </button>

          <button
            onClick={() => {
              // Generate billing report as JSON
              const reportData = {
                report_title: "AP2 Expense Agent - Billing Report",
                generated_at: new Date().toISOString(),
                organization: {
                  name: organization?.name || "N/A",
