              document.body.removeChild(link);
              URL.revokeObjectURL(url);
              success("Billing report exported as JSON");
            }}
            className="inline-flex items-center gap-2 px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
          >
