const BudgetManagement = () => {
  const { user } = useAuth();
  const { success: showSuccess, error: showError } = useToast();

  const [budgets, setBudgets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [selectedBudget, setSelectedBudget] = useState(null);
  const [filter, setFilter] = useState("all"); // all, on_track, warning, critical, exceeded
  const [showActiveOnly, setShowActiveOnly] = useState(true);

  // Fetch budgets
  useEffect(() => {
    fetchBudgets();
  }, [showActiveOnly]);

  const fetchBudgets = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem("access_token");
      const response = await fetch(
        `/api/budgets?active_only=${showActiveOnly}`,
        {
          headers: { Authorization: `Bearer ${token}` },
        },
      );

      if (!response.ok) {
        throw new Error("Failed to load budgets");
      }

      const data = await response.json();
      setBudgets(data);
    } catch (err) {
      showError(err.message || "Failed to load budgets");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateBudget = () => {
    setSelectedBudget(null);
    setShowBudgetForm(true);
  };

  const handleEditBudget = (budget) => {
    setSelectedBudget(budget);
    setShowBudgetForm(true);
  };

  const handleDeleteBudget = async (budgetId) => {
    if (
      !confirm(
        "Are you sure you want to delete this budget? This action cannot be undone.",
      )
    ) {
      return;
    }

    try {
      const token = localStorage.getItem("access_token");
      const response = await fetch(`/api/budgets/${budgetId}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "Failed to delete budget");
      }

      showSuccess("Budget deleted successfully");
      fetchBudgets();
    } catch (err) {
      showError(err.message || "Failed to delete budget");
      console.error(err);
    }
  };

  const handleBudgetFormSuccess = () => {
    setShowBudgetForm(false);
    setSelectedBudget(null);
    fetchBudgets();
  };

  // Calculate stats
  const stats = budgets.reduce(
    (acc, budget) => {
      acc.total++;
      if (budget.status === "on_track") acc.on_track++;
      if (budget.status === "warning") acc.warning++;
      if (budget.status === "critical") acc.critical++;
      if (budget.status === "exceeded") acc.exceeded++;
      acc.totalBudget += budget.amount;
      acc.totalSpent += budget.current_spending;
      return acc;
    },
    {
      total: 0,
      on_track: 0,
      warning: 0,
      critical: 0,
      exceeded: 0,
      totalBudget: 0,
      totalSpent: 0,
    },
  );

  // Filter budgets
  const filteredBudgets =
    filter === "all" ? budgets : budgets.filter((b) => b.status === filter);

  const getStatusColor = (status) => {
    switch (status) {
      case "on_track":
        return "bg-green-100 text-green-800";
      case "warning":
        return "bg-yellow-100 text-yellow-800";
      case "critical":
        return "bg-orange-100 text-orange-800";
      case "exceeded":
        return "bg-red-100 text-red-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case "on_track":
        return <CheckCircle className="w-4 h-4" />;
      case "warning":
        return <AlertTriangle className="w-4 h-4" />;
      case "critical":
        return <AlertTriangle className="w-4 h-4" />;
      case "exceeded":
        return <AlertTriangle className="w-4 h-4" />;
      default:
        return null;
    }
  };

  const getProgressBarColor = (status) => {
    switch (status) {
      case "on_track":
        return "bg-green-500";
      case "warning":
        return "bg-yellow-500";
      case "critical":
        return "bg-orange-500";
      case "exceeded":
        return "bg-red-500";
      default:
        return "bg-gray-500";
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(amount);
  };

  const isAdmin = user?.role === "admin";
  const isManager = user?.role === "manager";
  const canManageBudgets = isAdmin || isManager;

  return (
