/**
 * API Client with Automatic Token Refresh
 *
 * This utility provides a fetch wrapper that automatically refreshes
 * expired tokens when receiving 401 errors.
 *
 * Usage:
 * import { apiFetch } from '../utils/apiClient';
 * const response = await apiFetch('/api/endpoint', { method: 'POST', body: ... });
 */

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || "";

/**
 * Get authentication headers
 */
const getAuthHeaders = () => {
  const token = localStorage.getItem("access_token");
  return {
    "Content-Type": "application/json",
    Authorization: `Bearer ${token}`,
  };
};

/**
 * Refresh the access token using the refresh token
 */
const refreshAccessToken = async () => {
  const refreshToken = localStorage.getItem("refresh_token");

  if (!refreshToken) {
    throw new Error("No refresh token available");
  }

  const response = await fetch(`${API_BASE_URL}/api/v1/auth/refresh`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ refresh_token: refreshToken }),
  });

  if (!response.ok) {
    // Refresh token is invalid/expired, clear everything
    localStorage.removeItem("access_token");
    localStorage.removeItem("refresh_token");
    localStorage.removeItem("user");
    localStorage.removeItem("current_organization_id");

    // Redirect to login
    window.location.href = "/login";
    throw new Error("Session expired. Please login again.");
  }

  const data = await response.json();
  localStorage.setItem("access_token", data.access_token);

  return data.access_token;
};

/**
 * Enhanced fetch with automatic token refresh
 *
 * @param {string} url - API endpoint URL (can be relative or absolute)
 * @param {object} options - Fetch options (method, body, headers, etc.)
 * @returns {Promise<Response>} - Fetch response
 */
export const apiFetch = async (url, options = {}) => {
  // Merge auth headers with any custom headers
  const headers = {
    ...getAuthHeaders(),
    ...options.headers,
  };

  // Make initial request
  let response = await fetch(url, {
    ...options,
    headers,
  });

  // If we get 401 Unauthorized, try to refresh token and retry
  if (response.status === 401) {
    try {
      const newAccessToken = await refreshAccessToken();

      // Retry the request with new token
      const retryHeaders = {
        ...headers,
        Authorization: `Bearer ${newAccessToken}`,
      };

      response = await fetch(url, {
        ...options,
        headers: retryHeaders,
      });
    } catch (error) {
      // Token refresh failed, user will be redirected to login
      throw error;
    }
  }

  // If account is suspended/inactive, clear session and redirect
  if (response.status === 403) {
    try {
      const errorData = await response.clone().json();
      if (errorData.detail === "User account is inactive") {
        localStorage.removeItem("access_token");
        localStorage.removeItem("refresh_token");
        localStorage.removeItem("user");
        localStorage.removeItem("current_organization_id");

        window.location.href = "/login";
        throw new Error("Your account has been suspended. Please contact your administrator.");
      }
    } catch (error) {
      // If it's already our custom error, re-throw it
      if (error.message && error.message.includes("suspended")) {
        throw error;
      }
      // Otherwise, it's a different 403 error, let it pass through
    }
  }

  return response;
};

export default apiFetch;

/**
 * API Error Handler Utility
 *
 * Ensures all API errors have consistent structure with status and data properties.
 * This is critical for proper error handling in components (e.g., showing upgrade modals for 402 errors).
 */

/**
 * Creates a standardized API error with status and data properties
 *
 * @param {Response} response - Fetch API response object
 * @param {Object} errorData - Parsed error JSON from response
 * @returns {Error} Error object with status and data properties
 *
 * @example
 * const response = await fetch('/api/endpoint');
 * if (!response.ok) {
 *   const errorData = await response.json();
 *   throw createAPIError(response, errorData);
 * }
 */
export function createAPIError(response, errorData) {
  // DEBUG: Log the raw error data
  console.log('[apiErrorHandler] Raw error data:', JSON.stringify(errorData, null, 2));
  console.log('[apiErrorHandler] Response status:', response.status);

  // Extract the most user-friendly error message
  let message = "An error occurred";

  // PRIORITY 1: Check for new backend error format with "error" object
  if (errorData.error && typeof errorData.error === "object") {
    console.log('[apiErrorHandler] Found error object format');

    // Check for validation errors in details.errors array (422 errors)
    if (errorData.error.details && Array.isArray(errorData.error.details.errors)) {
      console.log('[apiErrorHandler] Found validation errors array:', errorData.error.details.errors);
      const errors = errorData.error.details.errors.map(err => {
        const field = err.field ? err.field.split('.').pop() : 'field'; // Extract last part of "body.slug"
        let msg = err.message || 'Validation error';

        // Make validation messages more user-friendly
        if (msg.includes('at least 3 characters')) {
          msg = 'must be at least 3 characters long';
        } else if (msg.includes('string does not match regex')) {
          msg = 'can only contain lowercase letters, numbers, and hyphens';
        }

        return `${field}: ${msg}`;
      });
      message = errors.join(', ');
      console.log('[apiErrorHandler] Formatted validation message:', message);
    } else if (errorData.error.message) {
      // Use the error.message field
      message = errorData.error.message;
      console.log('[apiErrorHandler] Using error.message:', message);
    }
  }
  // PRIORITY 2: Legacy format with "detail" (for compatibility)
  else if (errorData.detail) {
    console.log('[apiErrorHandler] Found legacy detail format');
    if (typeof errorData.detail === "string") {
      // Simple string detail
      message = errorData.detail;
    } else if (Array.isArray(errorData.detail) && errorData.detail.length > 0) {
      // Pydantic validation errors array (old format)
      const errors = errorData.detail.map(err => {
        const field = err.loc ? err.loc[err.loc.length - 1] : 'field';
        let msg = err.msg || 'Validation error';

        // Make validation messages more user-friendly
        if (msg.includes('at least 3 characters')) {
          msg = 'must be at least 3 characters long';
        } else if (msg.includes('string does not match regex')) {
          msg = 'can only contain lowercase letters, numbers, and hyphens';
        }

        return `${field}: ${msg}`;
      });
      message = errors.join(', ');
    } else if (typeof errorData.detail === "object") {
      // Structured detail object (e.g., 402 Payment Required)
      message =
        typeof errorData.detail.message === "string" ? errorData.detail.message :
        typeof errorData.detail.upgrade_message === "string" ? errorData.detail.upgrade_message :
        typeof errorData.detail.error === "string" ? errorData.detail.error :
        message;
    }
  } else if (errorData.message) {
    message = typeof errorData.message === "string" ? errorData.message : message;
  }

  console.log('[apiErrorHandler] Final message:', message);

  // Create error with message
  const error = new Error(message);

  // CRITICAL: Attach status and data for proper error handling
  error.status = response.status;
  error.data = errorData;

  // Add helper method to check error type
  error.is402PaymentRequired = () => error.status === 402;
  error.is401Unauthorized = () => error.status === 401;
  error.is403Forbidden = () => error.status === 403;
  error.is404NotFound = () => error.status === 404;
  error.is422ValidationError = () => error.status === 422;

  return error;
}

/**
 * Handles fetch response and throws standardized error if not ok
 *
 * @param {Response} response - Fetch API response object
 * @returns {Promise<any>} Parsed JSON response if ok
 * @throws {Error} Standardized API error with status and data
 *
 * @example
 * const data = await handleResponse(response);
 */
export async function handleResponse(response) {
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw createAPIError(response, errorData);
  }

  return response.json();
}

/**
 * Check if error is a tier limit error (402 Payment Required)
 *
 * @param {Error} error - Error object to check
 * @returns {boolean} True if it's a 402 tier limit error
 *
 * @example
 * catch (err) {
 *   if (isTierLimitError(err)) {
 *     // Show upgrade modal
 *   }
 * }
 */
export function isTierLimitError(error) {
  return error && error.status === 402;
}

/**
 * Extract tier limit info from 402 error for upgrade modal
 *
 * @param {Error} error - 402 error object
 * @returns {Object} Tier info for upgrade modal
 *
 * @example
 * if (isTierLimitError(err)) {
 *   const tierInfo = extractTierLimitInfo(err);
 *   setUpgradeTierInfo(tierInfo);
 *   setShowUpgradePrompt(true);
 * }
 */
export function extractTierLimitInfo(error) {
  if (!isTierLimitError(error)) {
    return null;
  }

  // Handle both new format (error.details) and legacy format (detail)
  const errorData = error.data?.error?.details || error.data?.detail || error.data || {};

  return {
    currentTier: errorData.current_tier || "Free",
    currentLimit: errorData.limit || 1,
    currentCount: errorData.current || 1,
    message:
      typeof errorData.message === "string"
        ? errorData.message
        : errorData.upgrade_message ||
          "You have reached your plan's limit. Upgrade to unlock more features.",
    upgradeOptions: errorData.upgrade_options || { next_tier: "Starter" },
  };
}

/**
 * VALIDATION: Ensures error has required properties for component error handling
 * This function is used in development to catch errors early.
 *
 * @param {Error} error - Error to validate
 * @throws {Error} If error is missing required properties
 */
export function validateAPIError(error) {
  if (!(error instanceof Error)) {
    throw new Error(
      "API error must be an Error instance. Use createAPIError() to create errors."
    );
  }

  if (typeof error.status !== "number") {
    console.error("Invalid API error:", error);
    throw new Error(
      `API error is missing 'status' property. Error: ${error.message}`
    );
  }

  if (!error.data) {
    console.warn(
      `API error is missing 'data' property. Status: ${error.status}, Message: ${error.message}`
    );
  }

  return true;
}

// Export all functions
export default {
  createAPIError,
  handleResponse,
  isTierLimitError,
  extractTierLimitInfo,
  validateAPIError,
};

/**
 * Excel File Safety Utilities
 * Mitigates xlsx library vulnerabilities (Prototype Pollution + ReDoS)
 *
 * Security Mitigations:
 * 1. File size limits (10MB max) - prevents oversized attacks
 * 2. Parsing timeout (5 seconds) - prevents ReDoS attacks
 * 3. Workbook structure validation - prevents memory exhaustion
 * 4. Error handling - prevents app crashes
 *
 * See: DEPENDENCY_AUDIT_REPORT.md for vulnerability details
 */

// Maximum file size: 10MB (prevents DoS via large files)
const MAX_FILE_SIZE = 10 * 1024 * 1024;

// Parsing timeout: 5 seconds (prevents ReDoS attacks)
const PARSING_TIMEOUT_MS = 5000;

// Maximum number of sheets to process
const MAX_SHEETS = 100;

// Maximum rows per sheet
const MAX_ROWS_PER_SHEET = 100000;

/**
 * Validate file size before processing
 * @param {File} file - File object to validate
 * @throws {Error} If file exceeds maximum size
 */
export function validateFileSize(file) {
  if (!file) {
    throw new Error('No file provided');
  }

  if (file.size > MAX_FILE_SIZE) {
    const sizeMB = (file.size / (1024 * 1024)).toFixed(2);
    const maxSizeMB = (MAX_FILE_SIZE / (1024 * 1024)).toFixed(0);
    throw new Error(
      `File too large: ${sizeMB}MB. Maximum size: ${maxSizeMB}MB`
    );
  }
}

/**
 * Validate MIME type
 * @param {File} file - File object to validate
 * @throws {Error} If file type is not Excel
 */
export function validateFileType(file) {
  const validTypes = [
    'application/vnd.ms-excel', // .xls
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', // .xlsx
    'text/csv', // .csv
  ];

  const validExtensions = ['.xls', '.xlsx', '.csv'];
  const fileName = file.name.toLowerCase();
  const hasValidExtension = validExtensions.some(ext => fileName.endsWith(ext));

  if (!validTypes.includes(file.type) && !hasValidExtension) {
    throw new Error(
      'Invalid file type. Please upload an Excel file (.xls, .xlsx) or CSV file.'
    );
  }
}

/**
 * Parse Excel file with timeout protection
 * Wraps parsing in a Promise.race to enforce timeout
 *
 * @param {Function} parseFunction - Function that parses the file (returns Promise)
 * @param {number} timeout - Timeout in milliseconds (default: 5000ms)
 * @returns {Promise} Parsed result or timeout error
 */
export async function parseWithTimeout(parseFunction, timeout = PARSING_TIMEOUT_MS) {
  return Promise.race([
    parseFunction(),
    new Promise((_, reject) =>
      setTimeout(
        () => reject(new Error('Excel parsing timeout. File may be corrupted or too complex.')),
        timeout
      )
    ),
  ]);
}

/**
 * Validate workbook structure after parsing
 * Prevents memory exhaustion attacks
 *
 * @param {Object} workbook - Parsed workbook object
 * @throws {Error} If workbook structure is invalid or excessive
 */
export function validateWorkbookStructure(workbook) {
  if (!workbook || !workbook.SheetNames) {
    throw new Error('Invalid workbook structure');
  }

  // Check number of sheets
  if (workbook.SheetNames.length > MAX_SHEETS) {
    throw new Error(
      `Too many sheets: ${workbook.SheetNames.length}. Maximum: ${MAX_SHEETS}`
    );
  }

  // Check rows per sheet
  workbook.SheetNames.forEach(sheetName => {
    const sheet = workbook.Sheets[sheetName];
    if (!sheet) return;

    // Get sheet range
    const range = sheet['!ref'];
    if (!range) return;

    // Parse range (e.g., "A1:Z1000")
    const match = range.match(/[A-Z]+(\d+):[A-Z]+(\d+)/);
    if (match) {
      const startRow = parseInt(match[1], 10);
      const endRow = parseInt(match[2], 10);
      const rowCount = endRow - startRow + 1;

      if (rowCount > MAX_ROWS_PER_SHEET) {
        throw new Error(
          `Sheet "${sheetName}" has too many rows: ${rowCount}. Maximum: ${MAX_ROWS_PER_SHEET}`
        );
      }
    }
  });
}

/**
 * Safe Excel file parser with all security mitigations
 *
 * Usage:
 * ```js
 * import { safeParseExcel } from './utils/excelSafety';
 *
 * try {
 *   const workbook = await safeParseExcel(file, (file) => {
 *     return new Promise((resolve) => {
 *       const reader = new FileReader();
 *       reader.onload = (e) => {
 *         const data = new Uint8Array(e.target.result);
 *         const workbook = XLSX.read(data, { type: 'array' });
 *         resolve(workbook);
 *       };
 *       reader.readAsArrayBuffer(file);
 *     });
 *   });
 *   // Process workbook safely
 * } catch (error) {
 *   // Handle error (file too large, timeout, invalid structure, etc.)
 * }
 * ```
 *
 * @param {File} file - File object to parse
 * @param {Function} parseFunction - Custom parsing function
 * @param {Object} options - Options { timeout, skipValidation }
 * @returns {Promise<Object>} Parsed workbook
 */
export async function safeParseExcel(file, parseFunction, options = {}) {
  const {
    timeout = PARSING_TIMEOUT_MS,
    skipSizeValidation = false,
    skipTypeValidation = false,
    skipStructureValidation = false,
  } = options;

  // Step 1: Validate file size
  if (!skipSizeValidation) {
    validateFileSize(file);
  }

  // Step 2: Validate file type
  if (!skipTypeValidation) {
    validateFileType(file);
  }

  // Step 3: Parse with timeout protection
  const workbook = await parseWithTimeout(
    () => parseFunction(file),
    timeout
  );

  // Step 4: Validate workbook structure
  if (!skipStructureValidation) {
    validateWorkbookStructure(workbook);
  }

  return workbook;
}

/**
 * Create a sanitized error message for user display
 * Prevents information disclosure
 *
 * @param {Error} error - Original error
 * @returns {string} User-friendly error message
 */
export function getSafeErrorMessage(error) {
  const message = error.message || 'Unknown error';

  // Known safe error messages
  const safeMessages = [
    'File too large',
    'Invalid file type',
    'Excel parsing timeout',
    'Too many sheets',
    'Invalid workbook structure',
  ];

  // Check if error message contains safe keywords
  const isSafe = safeMessages.some(safe => message.includes(safe));

  if (isSafe) {
    return message;
  }

  // Generic error for unexpected issues
  return 'Unable to process Excel file. Please ensure the file is valid and not corrupted.';
}

export default {
  validateFileSize,
  validateFileType,
  parseWithTimeout,
  validateWorkbookStructure,
  safeParseExcel,
  getSafeErrorMessage,
  MAX_FILE_SIZE,
  PARSING_TIMEOUT_MS,
};

/**
 * Excel Security Utilities
 *
 * Safety rails for Excel export/import operations.
 * We use ExcelJS (browser build) to avoid known xlsx CVEs and still
 * enforce resource limits and timeouts as defense-in-depth.
 */

// Security constants
export const EXCEL_SECURITY = {
  MAX_FILE_SIZE: 10 * 1024 * 1024, // 10MB
  MAX_FILE_SIZE_LABEL: "10MB",
  PARSING_TIMEOUT: 5000, // 5 seconds
  PARSING_TIMEOUT_LABEL: "5 seconds",
  MAX_ROWS: 50000, // Safety limit for row count
  MAX_COLUMNS: 100, // Safety limit for column count
};

/**
 * Validates file size before processing
 * @param {File} file - File object to validate
 * @throws {Error} If file exceeds size limit
 */
export function validateFileSize(file) {
  if (!file) {
    throw new Error("No file provided");
  }

  if (file.size > EXCEL_SECURITY.MAX_FILE_SIZE) {
    throw new Error(
      `File too large. Maximum size: ${EXCEL_SECURITY.MAX_FILE_SIZE_LABEL}. ` +
        `Your file: ${(file.size / 1024 / 1024).toFixed(2)}MB`,
    );
  }

  return true;
}

/**
 * Validates file type
 * @param {File} file - File object to validate
 * @param {string[]} allowedTypes - Allowed MIME types
 * @throws {Error} If file type is not allowed
 */
export function validateFileType(
  file,
  allowedTypes = [
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", // .xlsx
    "application/vnd.ms-excel", // .xls
    "text/csv", // .csv
  ],
) {
  if (!file) {
    throw new Error("No file provided");
  }

  if (!allowedTypes.includes(file.type)) {
    throw new Error(
      `Invalid file type. Allowed types: ${allowedTypes.join(", ")}`,
    );
  }

  return true;
}

/**
 * Execute a promise with timeout
 * @param {Promise} promise - Promise to execute
 * @param {number} timeoutMs - Timeout in milliseconds
 * @returns {Promise} Promise that resolves or rejects based on timeout
 */
export function withTimeout(
  promise,
  timeoutMs = EXCEL_SECURITY.PARSING_TIMEOUT,
) {
  return Promise.race([
    promise,
    new Promise((_, reject) =>
      setTimeout(
        () =>
          reject(
            new Error(
              `Operation timed out after ${timeoutMs / 1000} seconds. ` +
                `This may indicate a malformed or overly complex file.`,
            ),
          ),
        timeoutMs,
      ),
    ),
  ]);
}

/**
 * Safely parse Excel file with timeout protection
 * @param {Function} parseFunction - Function that parses the file
 * @param {any} args - Arguments to pass to parse function
 * @param {number} timeout - Timeout in milliseconds
 * @returns {Promise} Parsed data or error
 */
export async function safeExcelParse(
  parseFunction,
  args,
  timeout = EXCEL_SECURITY.PARSING_TIMEOUT,
) {
  try {
    return await withTimeout(Promise.resolve(parseFunction(args)), timeout);
  } catch (error) {
    console.error("Excel parsing error:", error);
    throw error;
  }
}

/**
 * Validate workbook structure to prevent excessive memory usage
 * @param {Object} workbook - ExcelJS workbook object (or compatible shape)
 * @throws {Error} If workbook structure is dangerous
 */
export function validateWorkbookStructure(workbook) {
  if (!workbook) {
    throw new Error("Invalid workbook structure");
  }

  const sheets =
    workbook.worksheets ||
    (workbook.SheetNames
      ? workbook.SheetNames.map((name) => workbook.Sheets?.[name]).filter(
          Boolean,
        )
      : []);

  if (!sheets.length) {
    throw new Error("Invalid workbook structure");
  }

  if (sheets.length > 50) {
    throw new Error(`Too many sheets. Maximum: 50. Found: ${sheets.length}`);
  }

  // Validate each sheet
  for (const sheet of sheets) {
    // ExcelJS exposes rowCount/columnCount; fall back to xlsx-style ranges
    const rowCount =
      typeof sheet.rowCount === "number"
        ? sheet.rowCount
        : sheet["!ref"]
          ? parseRange(sheet["!ref"])?.rows
          : 0;
    const colCount =
      typeof sheet.columnCount === "number"
        ? sheet.columnCount
        : sheet["!ref"]
          ? parseRange(sheet["!ref"])?.cols
          : 0;

    const sheetName = sheet.name || "Sheet";

    if (rowCount > EXCEL_SECURITY.MAX_ROWS) {
      throw new Error(
        `Sheet "${sheetName}" has too many rows. ` +
          `Maximum: ${EXCEL_SECURITY.MAX_ROWS}. Found: ${rowCount}`,
      );
    }

    if (colCount > EXCEL_SECURITY.MAX_COLUMNS) {
      throw new Error(
        `Sheet "${sheetName}" has too many columns. ` +
          `Maximum: ${EXCEL_SECURITY.MAX_COLUMNS}. Found: ${colCount}`,
      );
    }
  }

  return true;
}

/**
 * Parse Excel cell range (simplified version)
 * @param {string} range - Range string like "A1:Z100"
 * @returns {Object|null} Parsed range object
 */
function parseRange(range) {
  if (!range || typeof range !== "string") {
    return null;
  }

  try {
    const parts = range.split(":");
    if (parts.length !== 2) {
      return null;
    }

    const start = parseCell(parts[0]);
    const end = parseCell(parts[1]);

    if (!start || !end) {
      return null;
    }

    return {
      s: start, // start
      e: end, // end
      rows: end.r - start.r + 1,
      cols: end.c - start.c + 1,
    };
  } catch (error) {
    console.error("Range parsing error:", error);
    return null;
  }
}

/**
 * Parse Excel cell reference (simplified version)
 * @param {string} cell - Cell reference like "A1"
 * @returns {Object|null} Parsed cell object with row and column
 */
function parseCell(cell) {
  if (!cell || typeof cell !== "string") {
    return null;
  }

  const match = cell.match(/^([A-Z]+)(\d+)$/);
  if (!match) {
    return null;
  }

  const col = columnToIndex(match[1]);
  const row = parseInt(match[2], 10) - 1; // 0-indexed

  return { r: row, c: col };
}

/**
 * Convert column letters to index
 * @param {string} col - Column letters like "A" or "AB"
 * @returns {number} Column index (0-based)
 */
function columnToIndex(col) {
  let index = 0;
  for (let i = 0; i < col.length; i++) {
    index = index * 26 + (col.charCodeAt(i) - 65 + 1);
  }
  return index - 1; // 0-indexed
}

/**
 * Sanitize workbook data to prevent prototype pollution
 * Note: This is a defense-in-depth measure. The main protection
 * is that we only export (not import) Excel files in production.
 *
 * @param {Object} data - Data object to sanitize
 * @returns {Object} Sanitized data
 */
export function sanitizeWorkbookData(data) {
  if (!data || typeof data !== "object") {
    return data;
  }

  // Create new object without prototype chain
  const sanitized = Object.create(null);

  for (const key of Object.keys(data)) {
    // Skip dangerous keys
    if (key === "__proto__" || key === "constructor" || key === "prototype") {
      console.warn(`Skipping dangerous key: ${key}`);
      continue;
    }

    // Recursively sanitize nested objects
    if (data[key] && typeof data[key] === "object") {
      sanitized[key] = sanitizeWorkbookData(data[key]);
    } else {
      sanitized[key] = data[key];
    }
  }

  return sanitized;
}

/**
 * Create error message with security context
 * @param {Error} error - Original error
 * @param {string} context - Context of the error
 * @returns {string} User-friendly error message
 */
export function createSecureErrorMessage(error, context = "Excel operation") {
  // Don't expose internal error details
  const message = error.message || "Unknown error";

  // Check for known security-related errors
  if (message.includes("timeout")) {
    return "File processing timed out. The file may be too complex or corrupted.";
  }

  if (message.includes("too large") || message.includes("size")) {
    return message; // Size errors are safe to show
  }

  if (message.includes("too many")) {
    return message; // Validation errors are safe to show
  }

  // Generic error for unknown cases
  return `${context} failed. Please ensure the file is valid and not corrupted.`;
}

/**
 * Log security event (for monitoring)
 * In production, this should send to monitoring service
 * @param {string} event - Event name
 * @param {Object} details - Event details
 */
export function logSecurityEvent(event, details = {}) {
  const timestamp = new Date().toISOString();
  const logEntry = {
    timestamp,
    event,
    details,
    userAgent: navigator.userAgent,
  };

  // In development, log to console
  if (process.env.NODE_ENV === "development") {
    console.warn("[Security Event]", logEntry);
  }

  // In production, send to monitoring service
  // Example: sendToMonitoring(logEntry);
}

/**
 * All-in-one validation for Excel import operations
 * @param {File} file - File to validate
 * @throws {Error} If validation fails
 */
export function validateExcelImport(file) {
  try {
    validateFileSize(file);
    validateFileType(file);

    logSecurityEvent("excel_import_validation_passed", {
      fileName: file.name,
      fileSize: file.size,
      fileType: file.type,
    });

    return true;
  } catch (error) {
    logSecurityEvent("excel_import_validation_failed", {
      fileName: file?.name,
      fileSize: file?.size,
      fileType: file?.type,
      error: error.message,
    });

    throw error;
  }
}

export default {
  EXCEL_SECURITY,
  validateFileSize,
  validateFileType,
  withTimeout,
  safeExcelParse,
  validateWorkbookStructure,
  sanitizeWorkbookData,
  createSecureErrorMessage,
  logSecurityEvent,
  validateExcelImport,
};
